-- Member account transfer production release, 2026-10-08.
-- Generated by: node tools/build-account-transfer-release.mjs
-- Paste this ENTIRE file into the intended live project's Supabase SQL Editor
-- using the postgres role. Run once, without selecting only part of the script.
-- Confirm the project and retain the original transfer functions/ACLs first.
-- This applies only the new account-transfer migration. It does not run a
-- transfer, replay older migrations, or change any member history.
-- The schema changes, verification and migration-history entry are atomic.
-- Registered or partial releases fail before changes: inspect, do not rerun or
-- delete migration history. If an error leaves an aborted transaction open,
-- run ROLLBACK; before investigating. A timeout commits no release changes.
-- Source SHA-256 (LF): 66842f4fcbcf8c54120b173334c14555e11db069c7199cb9f5da76a701ed0edd

begin;
set local lock_timeout = '10s';
set local statement_timeout = '120s';
set local check_function_bodies = on;

do $release_preflight$
declare
  _name text;
  _column record;
begin
  if current_user not in ('postgres', 'supabase_admin') then
    raise exception 'Run this release through the intended project SQL Editor using the postgres role.';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('account-transfer-release-2026-10-08',0));
  if to_regclass('supabase_migrations.schema_migrations') is null then
    raise exception 'Migration history is missing. Confirm the project and initialize normal Supabase migration history first.';
  end if;
  if (select count(*) from information_schema.columns
      where table_schema='supabase_migrations' and table_name='schema_migrations'
        and ((column_name in ('version','name') and udt_name='text')
          or (column_name='statements' and udt_name='_text'))) <> 3 then
    raise exception 'Unexpected migration history schema: expected version text, name text, statements text[].';
  end if;
  lock table supabase_migrations.schema_migrations in share row exclusive mode;
  if exists(select 1 from supabase_migrations.schema_migrations where version='20261008000000') then
    raise exception 'Account-transfer release 20261008000000 is already registered. Do not rerun; inspect the recorded release and deployed application.';
  end if;
  foreach _name in array array['anon','authenticated','service_role'] loop
    if not exists(select 1 from pg_roles where rolname=_name) then
      raise exception 'Required Supabase role % is missing. Confirm the selected project.',_name;
    end if;
  end loop;
  foreach _name in array array[
    'auth.users',
    'public.user_merge_log',
    'public.user_merge_log_id_seq',
    'public.profiles',
    'public.roles',
    'public.user_roles',
    'public.coaching_notes_base',
    'public.coaching_note_action_steps',
    'public.coaching_note_comments',
    'public.business_reviews',
    'public.business_review_focus_values',
    'public.business_review_preparation_responses',
    'public.business_review_additional_scorecards',
    'public.business_review_system_ratings',
    'public.business_review_system_priorities',
    'public.system_scorecard_version_migrations',
    'public.implementation_action_checklists',
    'public.implementation_meeting_sessions',
    'public.implementation_session_actions',
    'public.implementation_step_notes',
    'public.implementation_step_events',
    'public.general_coaching_notes',
    'public.coaching_private_notes',
    'public.user_training_assignments',
    'public.member_pauses',
    'public.ninety_day_cycle_users',
    'public.member_home_preferences',
    'public.user_assistants',
    'public.wins',
    'public.monthly_kpi_records_base',
    'public.monthly_kpi_values',
    'public.meeting_attendance_base',
    'public.user_achievements',
    'public.user_course_visibility',
    'public.user_coaches',
    'public.partnerships',
    'public.partnership_users',
    'public.user_node_progress',
    'public.smart_doc_responses',
    'public.smart_doc_response_values',
    'public.resource_access',
    'public.search_analytics',
    'public.user_attention_status_log',
    'public.content_nodes',
    'public.resources',
    'public.smart_docs',
    'public.tags',
    'public.meetings',
    'public.system_implementation_guides',
    'public.system_implementation_guide_versions'
  ] loop
    if to_regclass(_name) is null then
      raise exception 'Missing prerequisite relation %. Apply/verify earlier Business Review, membership and implementation releases first.',_name;
    end if;
  end loop;
  if to_regtype('public.share_domain') is null then
    raise exception 'Missing prerequisite type public.share_domain.';
  end if;
  foreach _name in array array[
    'auth.role()',
    'public._jsonb_inc(jsonb,text[],bigint)',
    'public._jsonb_inc(jsonb,text[],integer)',
    'public._status_rank(text)',
    'public.canonical_owner_for(uuid,public.share_domain)',
    'public.get_current_member_ids()',
    'public.apply_user_attention_auto(uuid)',
    'public.transfer_user_data(uuid,uuid,jsonb)',
    'public.transfer_user_data_admin(uuid,uuid,jsonb)'
  ] loop
    if to_regprocedure(_name) is null then
      raise exception 'Missing prerequisite function %. Verify earlier releases; this script does not apply them.',_name;
    end if;
  end loop;
  for _column in select * from (values
    ('id','uuid'),
    ('note_id','int8'),
    ('meeting_id','int8'),
    ('user_id','uuid'),
    ('status','text'),
    ('revision','int4'),
    ('started_at','timestamptz'),
    ('updated_at','timestamptz'),
    ('completed_at','timestamptz'),
    ('updated_by','uuid'),
    ('notes','text'),
    ('commitments','text'),
    ('progress_snapshot','jsonb'),
    ('notes_written_at','timestamptz'),
    ('notes_author_id','uuid'),
    ('notes_updated_at','timestamptz'),
    ('notes_updated_by','uuid'),
    ('next_meeting_booked','bool')
  ) as required(column_name,udt_name) loop
    if not exists(select 1 from information_schema.columns actual
      where actual.table_schema='public' and actual.table_name='implementation_meeting_sessions'
        and actual.column_name=_column.column_name and actual.udt_name=_column.udt_name) then
      raise exception 'Missing or incompatible implementation session column % (%). Verify the coaching-history and next-meeting-booking releases.',_column.column_name,_column.udt_name;
    end if;
  end loop;
  foreach _name in array array[
    'public.transfer_user_data_admin_v2(uuid,uuid,jsonb)',
    'public.get_account_transfer_result_v2(uuid,uuid,jsonb)',
    'public.restore_account_transfer_smart_doc_metadata()'
  ] loop
    if to_regprocedure(_name) is not null then
      raise exception 'Unexpected existing release function %. This may be a partial/manual release; inspect before proceeding.',_name;
    end if;
  end loop;
  if to_regclass('public.user_merge_log_applied_request_id_idx') is not null
    or exists(select 1 from pg_trigger where tgname='zzz_account_transfer_metadata'
      and tgrelid in ('public.smart_doc_responses'::regclass,'public.smart_doc_response_values'::regclass)) then
    raise exception 'Existing account-transfer release index/trigger without migration history. Inspect this partial/manual release instead of rerunning.';
  end if;
end;
$release_preflight$;

-- Canonical migration body; only its outer BEGIN/COMMIT are omitted here.
-- Complete member-account copies after the implementation-workspace release.
-- Apply only after the 2026-09-29 implementation migrations. The earlier transfer
-- migration is intentionally left unchanged because it has already been applied.

-- Replay records contain verified identities and may only be written/read by
-- the server. The original schema exposed this table to browser roles.
alter table public.user_merge_log enable row level security;
revoke all on table public.user_merge_log from public, anon, authenticated;
revoke all on sequence public.user_merge_log_id_seq from public, anon, authenticated;

-- Successful executions share one durable idempotency key. Dry-run audit entries
-- do not consume the key. Old logs without request_id are unaffected.
create unique index if not exists user_merge_log_applied_request_id_idx
  on public.user_merge_log ((options->>'request_id'))
  where not dry_run and options ? 'request_id';

-- A lost response must be recoverable even when GHL is down or the Auth email
-- subsequently changes. Only user-selected copy settings define the request;
-- verified GHL identity is derived server data retained in the saved result.
create or replace function public.get_account_transfer_result_v2(
  _source uuid, _dest uuid, _options jsonb default '{}'::jsonb
) returns jsonb
language plpgsql security definer set search_path = pg_catalog, public
as $$
declare
  request_id uuid;
  previous public.user_merge_log%rowtype;
  requested_options jsonb;
  previous_options jsonb;
begin
  if session_user not in ('postgres', 'supabase_admin')
    and coalesce(auth.role(), '') <> 'service_role' then
    raise exception 'Account transfers must use the admin server endpoint.' using errcode = '42501';
  end if;
  if jsonb_typeof(_options) is distinct from 'object' then
    raise exception 'Transfer options must be an object.' using errcode = '22023';
  end if;
  request_id := nullif(_options->>'request_id', '')::uuid;
  if request_id is null or coalesce((_options->>'dry_run')::boolean, true) then return null; end if;
  select * into previous from public.user_merge_log
  where not dry_run and options->>'request_id' = request_id::text;
  if not found then return null; end if;
  requested_options := jsonb_build_object(
    'reassign_authorship', coalesce((_options->>'reassign_authorship')::boolean, false),
    'smart_doc_conflict', coalesce(_options->>'smart_doc_conflict', 'keep_latest_submitted'),
    'progress_json_merge', coalesce(_options->>'progress_json_merge', 'prefer_dest'),
    'kpi_merge', coalesce(_options->>'kpi_merge', 'prefer_source'));
  previous_options := jsonb_build_object(
    'reassign_authorship', coalesce((previous.options->>'reassign_authorship')::boolean, false),
    'smart_doc_conflict', coalesce(previous.options->>'smart_doc_conflict', 'keep_latest_submitted'),
    'progress_json_merge', coalesce(previous.options->>'progress_json_merge', 'prefer_dest'),
    'kpi_merge', coalesce(previous.options->>'kpi_merge', 'prefer_source'));
  -- Profile deletion nulls the audit foreign keys; the immutable result retains
  -- the original identities so that a completed operation remains recoverable.
  if coalesce(previous.source_user_id, (previous.result_json->>'source')::uuid) is distinct from _source
    or coalesce(previous.dest_user_id, (previous.result_json->>'dest')::uuid) is distinct from _dest
    or requested_options is distinct from previous_options then
    raise exception 'This transfer request ID has already been used with different parameters.' using errcode = '22023';
  end if;
  if previous.finished_at is null or previous.result_json is null then
    raise exception 'This transfer request has no completed result.' using errcode = '55000';
  end if;
  return previous.result_json;
end;
$$;
revoke all on function public.get_account_transfer_result_v2(uuid, uuid, jsonb) from public, anon, authenticated;
grant execute on function public.get_account_transfer_result_v2(uuid, uuid, jsonb) to service_role;

-- Normal Smart Doc writes stamp the current actor/time. A history copy is not
-- a new edit, so restore metadata from the actual source row after those normal
-- BEFORE triggers, only within the trusted transfer's tightly scoped context.
create or replace function public.restore_account_transfer_smart_doc_metadata()
returns trigger language plpgsql set search_path = pg_catalog, public
as $$
declare
  context_text text := nullif(current_setting('reboot.account_transfer_smart_docs', true), '');
  context jsonb;
  source_user uuid;
  dest_user uuid;
  original record;
begin
  if context_text is null or (session_user not in ('postgres', 'supabase_admin')
    and coalesce(auth.role(), '') <> 'service_role') then
    return new;
  end if;
  context := context_text::jsonb;
  source_user := (context->>'source')::uuid;
  dest_user := (context->>'dest')::uuid;
  if source_user is null or dest_user is null or source_user = dest_user then
    raise exception 'Invalid Smart Doc transfer context.' using errcode = '22023';
  end if;
  if tg_table_name = 'smart_doc_responses' then
    if new.user_id <> dest_user then return new; end if;
    select r.created_by, r.updated_by, r.updated_at into original
    from public.smart_doc_responses r
    where r.user_id = source_user and r.content_block_id = new.content_block_id;
  else
    select value.created_by, value.updated_by, value.updated_at into original
    from public.smart_doc_responses destination
    join public.smart_doc_responses source
      on source.content_block_id = destination.content_block_id and source.user_id = source_user
    join public.smart_doc_response_values value
      on value.response_id = source.id and value.prompt_id = new.prompt_id
    where destination.id = new.response_id and destination.user_id = dest_user;
  end if;
  if not found then
    raise exception 'Source Smart Doc metadata was not found during transfer.' using errcode = '23514';
  end if;
  new.created_by := original.created_by;
  new.updated_by := original.updated_by;
  new.updated_at := original.updated_at;
  return new;
end;
$$;
revoke all on function public.restore_account_transfer_smart_doc_metadata()
  from public, anon, authenticated, service_role;
drop trigger if exists zzz_account_transfer_metadata on public.smart_doc_responses;
create trigger zzz_account_transfer_metadata before insert or update on public.smart_doc_responses
  for each row execute function public.restore_account_transfer_smart_doc_metadata();
drop trigger if exists zzz_account_transfer_metadata on public.smart_doc_response_values;
create trigger zzz_account_transfer_metadata before insert or update on public.smart_doc_response_values
  for each row execute function public.restore_account_transfer_smart_doc_metadata();

CREATE OR REPLACE FUNCTION "public"."transfer_user_data"("_source" "uuid", "_dest" "uuid", "_options" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_started_at timestamptz := now();
  v_dry_run boolean := coalesce((_options->>'dry_run')::boolean, true);
  v_reassign_authorship boolean := coalesce((_options->>'reassign_authorship')::boolean, false);
  v_sdoc_strategy text := coalesce((_options->>'smart_doc_conflict'), 'keep_latest_submitted');
  v_progress_json_strategy text := coalesce((_options->>'progress_json_merge'), 'prefer_dest');
  v_kpi_merge_strategy text := coalesce((_options->>'kpi_merge'), 'prefer_source');

  v_log_id bigint;
  v_result jsonb := '{}'::jsonb;
  rec record;
  v_new_note_id bigint;
  v_new_response_id bigint;
  v_existing_response public.smart_doc_responses%rowtype;
  v_use_source_response boolean;
  v_new_review_id bigint;
  v_new_step_id bigint;
  v_new_session_id uuid;
  v_note_map jsonb := '{}'::jsonb;
  v_step_map jsonb := '{}'::jsonb;
  v_session_map jsonb := '{}'::jsonb;
  v_source_note_ids bigint[];
  v_source_session_ids uuid[];
  v_snapshot jsonb;
  v_step record;
  v_tmp_count bigint;
  v_course_visibility_count bigint;
  v_achievements_merged_count bigint;
  v_request_id uuid;
  v_destination_email text;
  v_destination_ghl_contact_id text;
  v_actual_email text;
  v_previous_smart_doc_context text;
  v_coach_seen_rows jsonb;
  v_coach_active_keys jsonb;
  v_coach_row_key text;
  v_coach_pair_key text;
  v_assistant_seen_rows jsonb;
  v_assistant_row_key text;

  c jsonb := '{
    "coaching_notes": {"moved":0},
    "action_steps": {"linked":0},
    "comments": {"linked":0},
    "wins": {"moved":0},
    "kpi_records": {"moved":0,"merged":0},
    "kpi_values": {"upserted":0},
    "attendance": {"moved":0,"merged":0},
    "achievements": {"moved":0,"merged":0,"skipped_dupe":0},
    "roles": {"added":0,"removed_source":0},
    "course_visibility": {"added":0,"removed_source":0},
    "user_coaches": {"moved":0,"merged":0},
    "partnership_users": {"moved":0,"skipped_dupe":0},
    "progress": {"moved":0,"merged":0},
    "smart_docs": {"reassigned":0,"drafted_older":0},
    "resource_access": {"moved":0},
    "search_analytics": {"moved":0},
    "attention_log": {"moved":0},
    "authorship": {"reassigned":0}
  }'::jsonb;
begin
  -- Only the guarded server route can supply an email-verified GHL contact.
  -- SECURITY DEFINER changes current_user; use session_user/JWT role instead.
  if session_user not in ('postgres', 'supabase_admin')
     and coalesce(auth.role(), '') <> 'service_role' then
    raise exception 'Account transfers must use the admin server endpoint.' using errcode = '42501';
  end if;
  if jsonb_typeof(_options) is distinct from 'object' then
    raise exception 'Transfer options must be an object.' using errcode = '22023';
  end if;
  -- Guardrails
  if _source is null or _dest is null or _source = _dest then
    raise exception 'Invalid source/dest';
  end if;

  -- Serialize copies sharing either account, regardless of transfer direction.
  perform pg_advisory_xact_lock(hashtextextended('account-transfer:' || least(_source::text, _dest::text), 0));
  perform pg_advisory_xact_lock(hashtextextended('account-transfer:' || greatest(_source::text, _dest::text), 0));

  v_request_id := nullif(_options->>'request_id', '')::uuid;
  if not v_dry_run and v_request_id is null then
    raise exception 'A transfer request ID is required.' using errcode = '22023';
  end if;
  if v_request_id is not null then
    _options := jsonb_set(_options, '{request_id}', to_jsonb(v_request_id::text));
    perform pg_advisory_xact_lock(hashtextextended('account-transfer-request:' || v_request_id::text, 0));
    if not v_dry_run then
      v_result := public.get_account_transfer_result_v2(_source, _dest, _options);
      if v_result is not null then return v_result; end if;
    end if;
  end if;

  perform 1 from public.profiles where id = _source;
  if not found then raise exception 'Source profile % not found', _source; end if;
  perform 1 from public.profiles where id = _dest;
  if not found then raise exception 'Destination profile % not found', _dest; end if;

  v_destination_email := lower(btrim(_options->>'destination_email'));
  v_destination_ghl_contact_id := nullif(btrim(_options->>'destination_ghl_contact_id'), '');
  if coalesce(v_destination_email, '') = '' or v_destination_ghl_contact_id is null then
    raise exception 'A verified destination email and GHL contact are required.' using errcode = '22023';
  end if;
  -- Keep an Auth email change from racing the server lookup and profile update.
  select lower(btrim(email)) into v_actual_email from auth.users where id = _dest for share;
  if v_actual_email is distinct from v_destination_email then
    raise exception 'The destination email changed. Preview the transfer again.' using errcode = '22023';
  end if;

  if v_kpi_merge_strategy not in ('prefer_source', 'skip', 'none')
    or v_sdoc_strategy not in ('keep_latest_submitted', 'keep_source', 'keep_dest')
    or v_progress_json_strategy not in ('prefer_dest', 'prefer_source', 'deep_merge') then
    raise exception 'Unsupported account transfer strategy.' using errcode = '22023';
  end if;

  if exists (select 1 from public.user_roles ur join public.roles r on r.id = ur.role_id
    where ur.user_id in (_source, _dest) and r.code in ('coach', 'implementation_coach')) then
    raise exception 'Staff accounts cannot be copied with the member-account transfer. Coach calendars and staff IDs need a separate migration.' using errcode = '23514';
  end if;
  if exists (select 1 from public.user_roles ur join public.roles r on r.id = ur.role_id
      where ur.user_id = _source and r.code = 'past_member')
    and exists (select 1 from public.get_current_member_ids() current_member where current_member.user_id = _dest) then
    raise exception 'The source is a past member but the destination is current. Resolve membership status before transferring.' using errcode = '23514';
  end if;
  if exists (select 1 from public.user_roles ur join public.roles r on r.id = ur.role_id
      where ur.user_id = _dest and r.code = 'past_member')
    and exists (select 1 from public.get_current_member_ids() current_member where current_member.user_id = _source) then
    raise exception 'The destination is a past member but the source is current. Resolve membership status before transferring.' using errcode = '23514';
  end if;

  -- Base-table triggers redirect writes to the partnership owner. Refuse to
  -- write a third person's history, even when the UI chose this destination.
  if public.canonical_owner_for(_dest, 'notes') <> _dest
    or public.canonical_owner_for(_dest, 'attendance') <> _dest
    or (v_kpi_merge_strategy not in ('skip', 'none') and public.canonical_owner_for(_dest, 'kpis') <> _dest) then
    raise exception 'The destination shares account data owned by a partner. Resolve partnership ownership before transferring.' using errcode = '23514';
  end if;
  if public.canonical_owner_for(_source, 'notes') <> _source
    or public.canonical_owner_for(_source, 'attendance') <> _source
    or (v_kpi_merge_strategy not in ('skip', 'none') and public.canonical_owner_for(_source, 'kpis') <> _source) then
    raise exception 'The source shares account data owned by a partner. Resolve partnership ownership before transferring.' using errcode = '23514';
  end if;
  if exists (
    select 1 from public.partnerships p
    join public.partnership_users source_member on source_member.partnership_id = p.id and source_member.user_id = _source
    where p.is_active and (p.shared_notes or p.shared_attendance or (p.shared_kpis and v_kpi_merge_strategy not in ('skip', 'none')))
      and not exists (select 1 from public.partnership_users d where d.partnership_id = p.id and d.user_id = _dest)
  ) then
    raise exception 'Adding the destination to a shared partnership would redirect copied account data. Resolve partnership ownership before transferring.' using errcode = '23514';
  end if;

  -- One snapshot of the graph also includes legacy shared notes explicitly
  -- referenced by this member's review, training assignment or workspace.
  select coalesce(array_agg(n.id), '{}'::bigint[]) into v_source_note_ids
  from public.coaching_notes_base n
  where n.user_id = _source
    or exists (select 1 from public.business_reviews r where r.user_id = _source and r.coaching_note_id = n.id)
    or exists (select 1 from public.implementation_meeting_sessions s where s.user_id = _source and s.note_id = n.id)
    or exists (select 1 from public.user_training_assignments a where a.user_id = _source and a.coaching_note_id = n.id);
  -- Workspace mutations also lock their note row, so no half-saved history can
  -- enter the copy. Child changes are otherwise covered by the same transaction.
  perform 1 from public.coaching_notes_base where id = any(v_source_note_ids) order by id for update;
  select coalesce(array_agg(id), '{}'::uuid[]) into v_source_session_ids
  from public.implementation_meeting_sessions where user_id = _source;
  if exists (
    select 1 from public.implementation_meeting_sessions s
    cross join lateral jsonb_array_elements(s.progress_snapshot) item
    where s.id = any(v_source_session_ids) and (
      jsonb_typeof(item) is distinct from 'object'
      or jsonb_typeof(item->'actionStepId') is distinct from 'number'
      or not exists (select 1 from public.coaching_note_action_steps a
        where a.id::text = item->>'actionStepId' and a.coaching_note_id = s.note_id)
    )
  ) or exists (
    select 1 from public.implementation_session_actions sa
    join public.implementation_meeting_sessions s on s.id = sa.session_id
    join public.coaching_note_action_steps a on a.id = sa.action_step_id
    where s.id = any(v_source_session_ids) and a.coaching_note_id <> s.note_id
  ) then
    raise exception 'Implementation history references an action outside its copied coaching cycle.' using errcode = '23514';
  end if;
  if exists (
    select 1 from public.implementation_meeting_sessions s
    join public.implementation_meeting_sessions d on d.user_id = _dest and d.meeting_id = s.meeting_id
    where s.id = any(v_source_session_ids)
  ) then
    raise exception 'The destination already has implementation history for a source meeting. Resolve the duplicate meeting before transferring.' using errcode = '23505';
  end if;
  if exists (select 1 from public.user_training_assignments a
    join public.content_nodes n on n.id = a.course_node_id
    where a.user_id = _source and (n.node_type::text <> 'course' or n.state::text <> 'published')) then
    raise exception 'Source training history references an unpublished course. Resolve that assignment before transferring.' using errcode = '23514';
  end if;
  if exists (select 1 from public.user_assistants where user_id = _source and assistant_id = _dest) then
    raise exception 'The destination is an assistant on the source account. Resolve the assignment before transferring.' using errcode = '23514';
  end if;
  if exists (select 1 from public.user_assistants s join public.user_assistants d
    on d.user_id = _dest and d.is_active and (d.ended_at is null or d.ended_at > now())
    where s.user_id = _source and s.is_active and (s.ended_at is null or s.ended_at > now())
      and s.assistant_id <> d.assistant_id) then
    raise exception 'The two accounts have different active assistants. Resolve the assignments before transferring.' using errcode = '23514';
  end if;
  if exists (select 1 from public.ninety_day_cycle_users s
    join public.ninety_day_cycle_users d on d.user_id = _dest
    where s.user_id = _source and (
      (s.ended_at is null and d.ended_at is null and s.cycle_id <> d.cycle_id)
      or (s.cycle_id = d.cycle_id and (s.ended_at is distinct from d.ended_at or s.outcome is distinct from d.outcome))
    )) then
    raise exception 'The accounts have conflicting 90-day enrolments. Resolve the enrolments before transferring.' using errcode = '23514';
  end if;
  if exists (select 1 from public.member_pauses s join public.member_pauses d
    on d.user_id = _dest and d.ended_at is null
    where s.user_id = _source and s.ended_at is null
      and (s.started_at, s.reason, s.started_by) is distinct from (d.started_at, d.reason, d.started_by)) then
    raise exception 'The accounts have different open pauses. Resolve the pauses before transferring.' using errcode = '23514';
  end if;

  insert into public.user_merge_log (source_user_id, dest_user_id, started_at, dry_run, options)
  values (_source, _dest, v_started_at, v_dry_run, _options)
  returning id into v_log_id;

  -- Training and completed-action triggers may grant access/achievements before
  -- their copy sections. Report the pre-transfer comparison consistently.
  select count(*) into v_course_visibility_count from public.user_course_visibility s
  where s.user_id = _source and not exists (
    select 1 from public.user_course_visibility d where d.user_id = _dest and d.course_node_id = s.course_node_id);
  select count(*) into v_achievements_merged_count from public.user_achievements s
  where s.user_id = _source and exists (
    select 1 from public.user_achievements d where d.user_id = _dest and d.achievement_id = s.achievement_id);

  ----------------------------------------------------------------------
  -- 1) Coaching notes + action steps + comments (COPY)
  ----------------------------------------------------------------------
  v_tmp_count := (select count(*) from public.coaching_notes_base n
    where n.id = any(v_source_note_ids));
  c := public._jsonb_inc(c, ARRAY['coaching_notes','moved'], v_tmp_count);

  v_tmp_count := (
    select count(*)
    from public.coaching_note_action_steps s
    join public.coaching_notes_base n on s.coaching_note_id = n.id
    where n.id = any(v_source_note_ids)
  );
  c := public._jsonb_inc(c, ARRAY['action_steps','linked'], v_tmp_count);

  v_tmp_count := (
    select count(*)
    from public.coaching_note_comments s
    join public.coaching_notes_base n on s.coaching_note_id = n.id
    where n.id = any(v_source_note_ids)
  );
  c := public._jsonb_inc(c, ARRAY['comments','linked'], v_tmp_count);

  if not v_dry_run then
    for rec in
      select n.* from public.coaching_notes_base n
      where n.id = any(v_source_note_ids)
    loop
      insert into public.coaching_notes_base (
        user_id, coach_id, created_at, updated_at, m2_meeting_id, deleted_at, deleted_by
      ) values (
        _dest, rec.coach_id, rec.created_at, rec.updated_at, rec.m2_meeting_id,
        rec.deleted_at, rec.deleted_by
      )
      returning id into v_new_note_id;

      v_note_map := v_note_map || jsonb_build_object(rec.id::text, v_new_note_id);

      for v_step in
        select * from public.coaching_note_action_steps where coaching_note_id = rec.id
      loop
        insert into public.coaching_note_action_steps (
          coaching_note_id, label, library_item_id, status, created_at, updated_at
        ) values (
          v_new_note_id, v_step.label, v_step.library_item_id, v_step.status,
          v_step.created_at, v_step.updated_at
        ) returning id into v_new_step_id;
        v_step_map := v_step_map || jsonb_build_object(v_step.id::text, v_new_step_id);
      end loop;

      insert into public.coaching_note_comments (
        coaching_note_id, author_id, body, created_at
      )
      select
        v_new_note_id,
        cmt.author_id,
        cmt.body,
        cmt.created_at
      from public.coaching_note_comments cmt
      where cmt.coaching_note_id = rec.id;
    end loop;
  end if;

  ----------------------------------------------------------------------
  -- 1b) Business Reviews and all review-owned data (COPY).
  -- Historical JSON snapshots retain their original IDs as audit evidence.
  -- A meeting owns at most one review, so the copy cannot claim its meeting_id.
  -- The copied coaching note retains m2_meeting_id as the meeting reference.
  ----------------------------------------------------------------------
  c := c || jsonb_build_object('business_reviews', jsonb_build_object(
    'copied', (select count(*) from public.business_reviews where user_id = _source),
    'meeting_links_not_copied', (select count(*) from public.business_reviews
      where user_id = _source and meeting_id is not null)
  ));

  for rec in
    select * from (values
      ('business_review_focus_values'),
      ('business_review_preparation_responses'),
      ('business_review_additional_scorecards'),
      ('business_review_system_ratings'),
      ('business_review_system_priorities'),
      ('system_scorecard_version_migrations')
    ) as review_tables(table_name)
  loop
    execute format(
      'select count(*) from public.%I child join public.business_reviews review
       on review.id = child.business_review_id where review.user_id = $1', rec.table_name
    ) into v_tmp_count using _source;
    c := c || jsonb_build_object(rec.table_name, jsonb_build_object('copied', v_tmp_count));
  end loop;

  if not v_dry_run then
    for rec in select * from public.business_reviews where user_id = _source order by id
    loop
      insert into public.business_reviews (
        user_id, coach_id, coaching_note_id, focus_finder_template_key,
        review_date, status, completed_at, completed_by, created_at, updated_at,
        system_scorecard_template_key, meeting_id
      ) values (
        _dest, rec.coach_id, (v_note_map->>rec.coaching_note_id::text)::bigint,
        rec.focus_finder_template_key, rec.review_date, rec.status,
        rec.completed_at, rec.completed_by, rec.created_at, rec.updated_at,
        rec.system_scorecard_template_key, null
      ) returning id into v_new_review_id;

      insert into public.business_review_focus_values (
        business_review_id, template_key, dimension_id, value, updated_by, created_at, updated_at
      ) select v_new_review_id, template_key, dimension_id, value, updated_by, created_at, updated_at
        from public.business_review_focus_values where business_review_id = rec.id;

      insert into public.business_review_preparation_responses (
        business_review_id, business_forward_wins, personal_forward_wins,
        greatest_business_challenge, greatest_personal_challenge, desired_call_outcome,
        topics_to_discuss, business_rating, personal_rating, submitted_at, updated_at
      ) select v_new_review_id, business_forward_wins, personal_forward_wins,
          greatest_business_challenge, greatest_personal_challenge, desired_call_outcome,
          topics_to_discuss, business_rating, personal_rating, submitted_at, updated_at
        from public.business_review_preparation_responses where business_review_id = rec.id;

      -- Register the extra Foundation template before its ratings are validated.
      insert into public.business_review_additional_scorecards (
        business_review_id, template_key, assigned_by, created_at
      ) select v_new_review_id, template_key, assigned_by, created_at
        from public.business_review_additional_scorecards where business_review_id = rec.id;

      insert into public.business_review_system_ratings (
        business_review_id, template_key, system_id, status, reviewed_at,
        reviewed_by, updated_by, created_at, updated_at
      ) select v_new_review_id, template_key, system_id, status, reviewed_at,
          reviewed_by, updated_by, created_at, updated_at
        from public.business_review_system_ratings where business_review_id = rec.id;

      insert into public.business_review_system_priorities (
        business_review_id, system_id, position, action_step_id, starting_status, selected_at, selected_by
      ) select v_new_review_id, system_id, position,
          (v_step_map->>action_step_id::text)::bigint, starting_status, selected_at, selected_by
        from public.business_review_system_priorities where business_review_id = rec.id;

      insert into public.system_scorecard_version_migrations (
        business_review_id, from_template_key, to_template_key, migrated_by,
        resolution, previous_snapshot, created_at
      ) select v_new_review_id, from_template_key, to_template_key, migrated_by,
          resolution, previous_snapshot, created_at
        from public.system_scorecard_version_migrations where business_review_id = rec.id;
    end loop;
  end if;

  ----------------------------------------------------------------------
  -- 1c) Implementation workspaces and standalone coaching notes (COPY).
  -- Guide step UUIDs and meeting IDs are immutable shared references. Action
  -- IDs in snapshots are live links and must follow the copied action graph.
  ----------------------------------------------------------------------
  c := c || jsonb_build_object(
    'implementation_action_checklists', jsonb_build_object('copied', (
      select count(*) from public.implementation_action_checklists a
      join public.coaching_note_action_steps s on s.id = a.action_step_id
      where s.coaching_note_id = any(v_source_note_ids))),
    'implementation_meeting_sessions', jsonb_build_object('copied', cardinality(v_source_session_ids)),
    'implementation_session_actions', jsonb_build_object('copied', (
      select count(*) from public.implementation_session_actions where session_id = any(v_source_session_ids))),
    'implementation_step_notes', jsonb_build_object('copied', (
      select count(*) from public.implementation_step_notes where session_id = any(v_source_session_ids))),
    'implementation_step_events', jsonb_build_object('copied', (
      select count(*) from public.implementation_step_events where session_id = any(v_source_session_ids))),
    'general_coaching_notes', jsonb_build_object('copied', (
      select count(*) from public.general_coaching_notes where user_id = _source))
  );

  if not v_dry_run then
    insert into public.implementation_action_checklists (
      action_step_id, guide_id, guide_revision, steps, progress, created_at, updated_at
    ) select (v_step_map->>a.action_step_id::text)::bigint,
        a.guide_id, a.guide_revision, a.steps, a.progress, a.created_at, a.updated_at
      from public.implementation_action_checklists a
      join public.coaching_note_action_steps s on s.id = a.action_step_id
      where s.coaching_note_id = any(v_source_note_ids);

    for rec in select * from public.implementation_meeting_sessions
      where id = any(v_source_session_ids) order by started_at, id
    loop
      select coalesce(jsonb_agg(
        jsonb_set(item.value, '{actionStepId}', v_step_map->(item.value->>'actionStepId'))
        order by item.ordinality), '[]'::jsonb) into v_snapshot
      from jsonb_array_elements(rec.progress_snapshot) with ordinality item(value, ordinality);

      insert into public.implementation_meeting_sessions (
        note_id, meeting_id, user_id, status, revision, started_at, updated_at,
        completed_at, updated_by, notes, commitments, progress_snapshot,
        notes_written_at, notes_author_id, notes_updated_at, notes_updated_by, next_meeting_booked
      ) values (
        (v_note_map->>rec.note_id::text)::bigint, rec.meeting_id, _dest,
        rec.status, rec.revision, rec.started_at, rec.updated_at, rec.completed_at,
        rec.updated_by, rec.notes, rec.commitments, v_snapshot, rec.notes_written_at,
        rec.notes_author_id, rec.notes_updated_at, rec.notes_updated_by, rec.next_meeting_booked
      ) returning id into v_new_session_id;
      v_session_map := v_session_map || jsonb_build_object(rec.id::text, v_new_session_id);
    end loop;

    insert into public.implementation_session_actions (session_id, action_step_id)
    select (v_session_map->>session_id::text)::uuid, (v_step_map->>action_step_id::text)::bigint
    from public.implementation_session_actions where session_id = any(v_source_session_ids);

    insert into public.implementation_step_notes (
      session_id, action_step_id, step_id, body, author_id, created_at
    ) select (v_session_map->>session_id::text)::uuid, (v_step_map->>action_step_id::text)::bigint,
        step_id, body, author_id, created_at
      from public.implementation_step_notes where session_id = any(v_source_session_ids);

    insert into public.implementation_step_events (
      session_id, action_step_id, step_id, completed, created_by, created_at
    ) select (v_session_map->>session_id::text)::uuid, (v_step_map->>action_step_id::text)::bigint,
        step_id, completed, created_by, created_at
      from public.implementation_step_events where session_id = any(v_source_session_ids);

    insert into public.general_coaching_notes (id, user_id, author_id, body, created_at)
    select gen_random_uuid(), _dest, author_id, body, created_at
    from public.general_coaching_notes where user_id = _source;
  end if;

  ----------------------------------------------------------------------
  -- 1d) Other member coaching/lifecycle records introduced since the original
  -- transfer. Attribution remains the original author, never the copying admin.
  ----------------------------------------------------------------------
  c := c || jsonb_build_object(
    'coaching_private_notes', jsonb_build_object('copied', (
      select count(*) from public.coaching_private_notes where user_id = _source)),
    'user_training_assignments', jsonb_build_object('copied', (
      select count(*) from public.user_training_assignments where user_id = _source)),
    'member_pauses', jsonb_build_object('copied', (
      select count(*) from public.member_pauses s where s.user_id = _source and not exists (
        select 1 from public.member_pauses d where d.user_id = _dest
          and (d.started_at, d.ended_at, d.reason, d.started_by, d.ended_by)
            is not distinct from (s.started_at, s.ended_at, s.reason, s.started_by, s.ended_by)))),
    'ninety_day_cycle_users', jsonb_build_object(
      'copied', (select count(*) from public.ninety_day_cycle_users s where s.user_id = _source
        and not exists (select 1 from public.ninety_day_cycle_users d where d.user_id = _dest and d.cycle_id = s.cycle_id)),
      'merged', (select count(*) from public.ninety_day_cycle_users s where s.user_id = _source
        and exists (select 1 from public.ninety_day_cycle_users d where d.user_id = _dest and d.cycle_id = s.cycle_id))),
    'member_home_preferences', jsonb_build_object('copied', (
      select count(*) from public.member_home_preferences where user_id = _source
        and not exists (select 1 from public.member_home_preferences where user_id = _dest))),
    'user_assistants', jsonb_build_object('copied', 0, 'merged', 0, 'skipped_dupe', 0)
  );
  if not v_dry_run then
    insert into public.coaching_private_notes (user_id, author_id, body, created_at)
    select _dest, author_id, body, created_at from public.coaching_private_notes where user_id = _source;

    insert into public.user_training_assignments (
      user_id, course_node_id, coaching_note_id, assigned_by, assigned_at,
      context_label, due_at, ended_at, ended_by
    ) select _dest, course_node_id, (v_note_map->>coaching_note_id::text)::bigint,
        assigned_by, assigned_at, context_label, due_at, ended_at, ended_by
      from public.user_training_assignments where user_id = _source;

    insert into public.member_pauses (user_id, started_at, ended_at, reason, started_by, ended_by)
    select _dest, s.started_at, s.ended_at, s.reason, s.started_by, s.ended_by
    from public.member_pauses s where s.user_id = _source and not exists (
      select 1 from public.member_pauses d where d.user_id = _dest
        and (d.started_at, d.ended_at, d.reason, d.started_by, d.ended_by)
          is not distinct from (s.started_at, s.ended_at, s.reason, s.started_by, s.ended_by));

    insert into public.ninety_day_cycle_users (cycle_id, user_id, enrolled_at, ended_at, outcome)
    select cycle_id, _dest, enrolled_at, ended_at, outcome
    from public.ninety_day_cycle_users where user_id = _source
    on conflict (cycle_id, user_id) do update
      set enrolled_at = least(public.ninety_day_cycle_users.enrolled_at, excluded.enrolled_at);

    insert into public.member_home_preferences (user_id, default_home)
    select _dest, default_home from public.member_home_preferences where user_id = _source
    on conflict (user_id) do nothing;
  end if;

  select coalesce(jsonb_object_agg(jsonb_build_array(assistant_id,
      is_active and (ended_at is null or ended_at > now()), assigned_at, ended_at, assigned_by, notes)::text, true), '{}'::jsonb)
    into v_assistant_seen_rows from public.user_assistants where user_id = _dest;
  for rec in select * from public.user_assistants where user_id = _source order by id
  loop
    v_assistant_row_key := jsonb_build_array(rec.assistant_id,
      rec.is_active and (rec.ended_at is null or rec.ended_at > now()),
      rec.assigned_at, rec.ended_at, rec.assigned_by, rec.notes)::text;
    if v_assistant_seen_rows ? v_assistant_row_key then
      c := public._jsonb_inc(c, array['user_assistants','skipped_dupe'], 1);
    elsif rec.is_active and (rec.ended_at is null or rec.ended_at > now()) and exists (select 1 from public.user_assistants d
      where d.user_id = _dest and d.assistant_id = rec.assistant_id and d.is_active
        and (d.ended_at is null or d.ended_at > now())) then
      c := public._jsonb_inc(c, array['user_assistants','merged'], 1);
      if not v_dry_run then
        update public.user_assistants d set
          assigned_at = least(d.assigned_at, rec.assigned_at),
          ended_at = case when d.ended_at is null or rec.ended_at is null then null else greatest(d.ended_at, rec.ended_at) end,
          notes = case when d.notes is null then rec.notes when rec.notes is null or d.notes = rec.notes then d.notes
            else d.notes || E'\n\n' || rec.notes end
        where d.user_id = _dest and d.assistant_id = rec.assistant_id and d.is_active
          and (d.ended_at is null or d.ended_at > now());
      end if;
    else
      c := public._jsonb_inc(c, array['user_assistants','copied'], 1);
      if not v_dry_run then
        -- The active-pair index checks the flag alone. Clear obsolete flags
        -- without changing historical dates so a current assignment can coexist.
        update public.user_assistants set is_active = false
        where user_id = _dest and assistant_id = rec.assistant_id and is_active and ended_at <= now()
          and rec.is_active and (rec.ended_at is null or rec.ended_at > now());
        insert into public.user_assistants (user_id, assistant_id, is_active, assigned_at, ended_at, assigned_by, notes)
        values (_dest, rec.assistant_id, rec.is_active and (rec.ended_at is null or rec.ended_at > now()),
          rec.assigned_at, rec.ended_at, rec.assigned_by, rec.notes);
      end if;
    end if;
    v_assistant_seen_rows := v_assistant_seen_rows || jsonb_build_object(v_assistant_row_key, true);
  end loop;

  ----------------------------------------------------------------------
  -- 2) Wins (COPY)
  ----------------------------------------------------------------------
  v_tmp_count := (select count(*) from public.wins where user_id = _source);
  c := public._jsonb_inc(c, ARRAY['wins','moved'], v_tmp_count);

  if not v_dry_run then
    insert into public.wins (user_id, added_by, body, created_at)
    select _dest, added_by, body, created_at
    from public.wins
    where user_id = _source;
  end if;

  ----------------------------------------------------------------------
  -- 3) KPI: preserve the explicit source-replaces-destination strategy.
  -- Counts describe actual planned writes and disclose exactly what is replaced.
  ----------------------------------------------------------------------
  c := jsonb_set(c, '{kpi_records}', jsonb_build_object(
    'moved', case when v_kpi_merge_strategy in ('skip','none') then 0
      else (select count(*) from public.monthly_kpi_records_base where user_id = _source) end,
    'skipped', case when v_kpi_merge_strategy in ('skip','none')
      then (select count(*) from public.monthly_kpi_records_base where user_id = _source) else 0 end,
    'destination_records_replaced', case when v_kpi_merge_strategy in ('skip','none') then 0
      else (select count(*) from public.monthly_kpi_records_base where user_id = _dest) end));
  c := jsonb_set(c, '{kpi_values}', jsonb_build_object(
    'upserted', case when v_kpi_merge_strategy in ('skip','none') then 0
      else (select count(*) from public.monthly_kpi_values v join public.monthly_kpi_records_base r on r.id=v.monthly_kpi_record_id where r.user_id=_source) end,
    'skipped', case when v_kpi_merge_strategy in ('skip','none')
      then (select count(*) from public.monthly_kpi_values v join public.monthly_kpi_records_base r on r.id=v.monthly_kpi_record_id where r.user_id=_source) else 0 end,
    'destination_values_replaced', case when v_kpi_merge_strategy in ('skip','none') then 0
      else (select count(*) from public.monthly_kpi_values v join public.monthly_kpi_records_base r on r.id=v.monthly_kpi_record_id where r.user_id=_dest) end));
  if not v_dry_run and v_kpi_merge_strategy not in ('skip', 'none') then
    lock table public.monthly_kpi_records_base, public.monthly_kpi_values in share row exclusive mode;
    delete from public.monthly_kpi_values v using public.monthly_kpi_records_base r
      where v.monthly_kpi_record_id = r.id and r.user_id = _dest;
    delete from public.monthly_kpi_records_base where user_id = _dest;
    insert into public.monthly_kpi_records_base (
      user_id, period_start_date, created_at, last_updated_at, last_updated_by
    ) select _dest, period_start_date, created_at, last_updated_at, last_updated_by
      from public.monthly_kpi_records_base where user_id = _source;
    insert into public.monthly_kpi_values (monthly_kpi_record_id, metric_type_id, value)
    select d.id, v.metric_type_id, v.value from public.monthly_kpi_values v
      join public.monthly_kpi_records_base s on s.id = v.monthly_kpi_record_id and s.user_id = _source
      join public.monthly_kpi_records_base d on d.user_id = _dest and d.period_start_date = s.period_start_date;
  end if;

  ----------------------------------------------------------------------
  -- 4) Attendance (COPY)
  ----------------------------------------------------------------------
  v_tmp_count := (select count(*) from public.meeting_attendance_base where user_id = _source);
  c := public._jsonb_inc(c, ARRAY['attendance','moved'], v_tmp_count);

  v_tmp_count := (
    select count(*)
    from public.meeting_attendance_base s
    join public.meeting_attendance_base d
      on d.meeting_id = s.meeting_id
     and d.user_id = _dest
    where s.user_id = _source
  );
  c := public._jsonb_inc(c, ARRAY['attendance','merged'], v_tmp_count);

  if not v_dry_run then
    insert into public.meeting_attendance_base (meeting_id, user_id, attended, created_at, updated_at)
    select meeting_id, _dest, attended, created_at, updated_at
    from public.meeting_attendance_base
    where user_id = _source
    on conflict (meeting_id, user_id)
    do update set
      attended   = (excluded.attended or public.meeting_attendance_base.attended),
      created_at = least(public.meeting_attendance_base.created_at, excluded.created_at),
      updated_at = greatest(public.meeting_attendance_base.updated_at, excluded.updated_at);
  end if;

  ----------------------------------------------------------------------
  -- 5) Achievements (COPY)
  ----------------------------------------------------------------------
  v_tmp_count := (select count(*) from public.user_achievements where user_id = _source);
  c := public._jsonb_inc(c, ARRAY['achievements','moved'], v_tmp_count);

  c := public._jsonb_inc(c, ARRAY['achievements','merged'], v_achievements_merged_count);

  if not v_dry_run then
    with overlap as (
      select s.id as s_id, d.id as d_id, s.achieved_at as s_at, d.achieved_at as d_at,
             s.awarded_via as s_via, d.awarded_via as d_via
      from public.user_achievements s
      join public.user_achievements d
        on d.user_id = _dest
       and s.user_id = _source
       and d.achievement_id = s.achievement_id
    )
    update public.user_achievements d
       set achieved_at = least(d.achieved_at, o.s_at),
           awarded_via = case
                           when d.awarded_via = o.s_via then d.awarded_via
                           else 'reconcile'
                         end
      from overlap o
     where d.id = o.d_id;

    insert into public.user_achievements (user_id, achievement_id, achieved_at, awarded_via)
    select _dest, s.achievement_id, s.achieved_at, s.awarded_via
    from public.user_achievements s
    where s.user_id = _source
      and not exists (
        select 1
        from public.user_achievements d
        where d.user_id = _dest
          and d.achievement_id = s.achievement_id
      );
  end if;

  ----------------------------------------------------------------------
  -- 6) Roles (COPY)
  ----------------------------------------------------------------------
  v_tmp_count := (
    select count(*)
    from public.user_roles s
    where s.user_id = _source
      and not exists (
        select 1
        from public.user_roles d
        where d.user_id = _dest
          and d.role_id = s.role_id
      )
  );
  c := public._jsonb_inc(c, ARRAY['roles','added'], v_tmp_count);

  if not v_dry_run then
    insert into public.user_roles (user_id, role_id)
    select _dest, role_id
    from public.user_roles s
    where s.user_id = _source
      and not exists (
        select 1
        from public.user_roles d
        where d.user_id = _dest
          and d.role_id = s.role_id
      );
  end if;

  ----------------------------------------------------------------------
  -- 7) Course visibility (COPY)
  ----------------------------------------------------------------------
  c := public._jsonb_inc(c, ARRAY['course_visibility','added'], v_course_visibility_count);

  if not v_dry_run then
    insert into public.user_course_visibility (user_id, course_node_id)
    select _dest, course_node_id
    from public.user_course_visibility s
    where s.user_id = _source
      and not exists (
        select 1
        from public.user_course_visibility d
        where d.user_id = _dest
          and d.course_node_id = s.course_node_id
      );
  end if;

  ----------------------------------------------------------------------
  -- 8) Coach assignments: preserve separate historical intervals; merge only
  -- currently active assignments for the same coach/course/relationship.
  -- Track planned rows in both modes so previews also count repeated source
  -- assignments correctly before any destination writes exist.
  ----------------------------------------------------------------------
  c := jsonb_set(c, '{user_coaches}', jsonb_build_object('moved', 0, 'merged', 0, 'skipped_dupe', 0));
  select coalesce(jsonb_object_agg(jsonb_build_array(coach_id, course_id, relationship_type,
      is_active, assigned_at, ended_at)::text, true), '{}'::jsonb)
    into v_coach_seen_rows from public.user_coaches where user_id = _dest;
  select coalesce(jsonb_object_agg(jsonb_build_array(coach_id, course_id, relationship_type)::text, true), '{}'::jsonb)
    into v_coach_active_keys from public.user_coaches
    where user_id = _dest and is_active and (ended_at is null or ended_at > now());
  for rec in select * from public.user_coaches where user_id = _source order by assigned_at, id
  loop
    v_coach_row_key := jsonb_build_array(rec.coach_id, rec.course_id, rec.relationship_type,
      rec.is_active, rec.assigned_at, rec.ended_at)::text;
    v_coach_pair_key := jsonb_build_array(rec.coach_id, rec.course_id, rec.relationship_type)::text;
    if v_coach_seen_rows ? v_coach_row_key then
      c := public._jsonb_inc(c, array['user_coaches','skipped_dupe'], 1);
      continue;
    end if;
    v_coach_seen_rows := v_coach_seen_rows || jsonb_build_object(v_coach_row_key, true);
    if rec.is_active and (rec.ended_at is null or rec.ended_at > now())
      and v_coach_active_keys ? v_coach_pair_key then
      c := public._jsonb_inc(c, array['user_coaches','merged'], 1);
      if not v_dry_run then
        update public.user_coaches d set
          assigned_at = least(d.assigned_at, rec.assigned_at),
          ended_at = case when d.ended_at is null or rec.ended_at is null then null else greatest(d.ended_at, rec.ended_at) end
        where d.id = (select active.id from public.user_coaches active
          where active.user_id = _dest and active.coach_id = rec.coach_id
            and active.course_id is not distinct from rec.course_id and active.relationship_type = rec.relationship_type
            and active.is_active and (active.ended_at is null or active.ended_at > now())
          order by active.assigned_at, active.id limit 1);
      end if;
    else
      c := public._jsonb_inc(c, array['user_coaches','moved'], 1);
      if rec.is_active and (rec.ended_at is null or rec.ended_at > now()) then
        v_coach_active_keys := v_coach_active_keys || jsonb_build_object(v_coach_pair_key, true);
      end if;
      if not v_dry_run then
        insert into public.user_coaches (user_id, coach_id, is_active, assigned_at, ended_at, course_id, relationship_type)
        values (_dest, rec.coach_id, rec.is_active, rec.assigned_at, rec.ended_at, rec.course_id, rec.relationship_type);
      end if;
    end if;
  end loop;

  ----------------------------------------------------------------------
  -- 9) Partnerships (COPY)
  ----------------------------------------------------------------------
  v_tmp_count := (select count(*) from public.partnership_users where user_id = _source);
  c := public._jsonb_inc(c, ARRAY['partnership_users','moved'], v_tmp_count);

  if not v_dry_run then
    insert into public.partnership_users (partnership_id, user_id)
    select partnership_id, _dest
    from public.partnership_users
    where user_id = _source
    on conflict (partnership_id, user_id) do nothing;
  end if;

  ----------------------------------------------------------------------
  -- 10) User node progress (COPY + merge on dest)
  ----------------------------------------------------------------------
  if v_dry_run then
    v_tmp_count := (select count(*) from public.user_node_progress s where user_id = _source
      and not exists (select 1 from public.user_node_progress d where d.user_id = _dest and d.node_id = s.node_id));
    c := public._jsonb_inc(c, ARRAY['progress','moved'], v_tmp_count);
    v_tmp_count := (select count(*) from public.user_node_progress s where user_id = _source
      and exists (select 1 from public.user_node_progress d where d.user_id = _dest and d.node_id = s.node_id));
    c := public._jsonb_inc(c, ARRAY['progress','merged'], v_tmp_count);
  else
    for rec in
      select
        s.node_id,
        s.status as s_status,
        s.first_started_at as s_start,
        s.completed_at as s_complete,
        s.progress_json as s_json,
        d.status as d_status,
        d.first_started_at as d_start,
        d.completed_at as d_complete,
        d.progress_json as d_json
      from public.user_node_progress s
      left join public.user_node_progress d
        on d.user_id = _dest
       and d.node_id = s.node_id
      where s.user_id = _source
    loop
      if rec.d_status is not null then
        update public.user_node_progress up
           set status = case
                          when public._status_rank(rec.d_status) >= public._status_rank(rec.s_status)
                            then rec.d_status
                          else rec.s_status
                        end,
               first_started_at = least(
                                    coalesce(rec.d_start, rec.s_start),
                                    coalesce(rec.s_start, rec.d_start)
                                  ),
               completed_at     = greatest(
                                    coalesce(rec.d_complete, rec.s_complete),
                                    coalesce(rec.s_complete, rec.d_complete)
                                  ),
               progress_json    = case v_progress_json_strategy
                                   when 'prefer_source' then rec.s_json
                                   when 'deep_merge' then
                                     coalesce(rec.d_json, '{}'::jsonb)
                                     || coalesce(rec.s_json, '{}'::jsonb)
                                   else rec.d_json
                                 end
         where up.user_id = _dest
           and up.node_id = rec.node_id;

        c := public._jsonb_inc(c, ARRAY['progress','merged'], 1);
      else
        insert into public.user_node_progress (
          user_id, node_id, status, first_started_at, completed_at, progress_json
        )
        values (
          _dest,
          rec.node_id,
          rec.s_status,
          rec.s_start,
          rec.s_complete,
          rec.s_json
        );

        c := public._jsonb_inc(c, ARRAY['progress','moved'], 1);
      end if;
    end loop;
  end if;

  ----------------------------------------------------------------------
  -- 11) Smart doc responses (+ values): one response per member/block.
  -- Keep each winning response and its values as a unit; never mix submitted
  -- metadata from one account with field values from another.
  ----------------------------------------------------------------------
  c := jsonb_set(c, '{smart_docs}', jsonb_build_object('reassigned', 0, 'merged', 0, 'kept_dest', 0));
  if not v_dry_run then
    v_previous_smart_doc_context := current_setting('reboot.account_transfer_smart_docs', true);
    perform set_config('reboot.account_transfer_smart_docs', jsonb_build_object('source', _source, 'dest', _dest)::text, true);
  end if;
  for rec in select * from public.smart_doc_responses where user_id = _source order by id
  loop
    select * into v_existing_response from public.smart_doc_responses
      where user_id = _dest and content_block_id = rec.content_block_id for update;
    v_use_source_response := v_existing_response.id is null or v_sdoc_strategy = 'keep_source';
    if v_existing_response.id is not null and v_sdoc_strategy = 'keep_latest_submitted' then
      v_use_source_response :=
        (case when rec.status = 'submitted' then 1 else 0 end,
         coalesce(rec.submitted_at, '-infinity'::timestamptz), rec.updated_at)
        > (case when v_existing_response.status = 'submitted' then 1 else 0 end,
           coalesce(v_existing_response.submitted_at, '-infinity'::timestamptz), v_existing_response.updated_at);
    end if;
    if not v_use_source_response then
      c := public._jsonb_inc(c, array['smart_docs','kept_dest'], 1);
      continue;
    end if;
    c := public._jsonb_inc(c, array['smart_docs',case when v_existing_response.id is null then 'reassigned' else 'merged' end], 1);
    if v_dry_run then continue; end if;
    if v_existing_response.id is null then
      insert into public.smart_doc_responses (
        content_block_id, user_id, status, started_at, submitted_at, created_by, updated_by, updated_at
      ) values (
        rec.content_block_id, _dest, rec.status, rec.started_at, rec.submitted_at,
        rec.created_by, rec.updated_by, rec.updated_at
      ) returning id into v_new_response_id;
    else
      v_new_response_id := v_existing_response.id;
      update public.smart_doc_responses set status = rec.status, started_at = rec.started_at,
        submitted_at = rec.submitted_at, created_by = rec.created_by,
        updated_by = rec.updated_by, updated_at = rec.updated_at where id = v_new_response_id;
      delete from public.smart_doc_response_values where response_id = v_new_response_id;
    end if;
    insert into public.smart_doc_response_values (
      response_id, prompt_id, value_json, created_by, updated_by, updated_at
    ) select v_new_response_id, prompt_id, value_json, created_by, updated_by, updated_at
      from public.smart_doc_response_values where response_id = rec.id;
  end loop;
  if not v_dry_run then
    perform set_config('reboot.account_transfer_smart_docs', coalesce(v_previous_smart_doc_context, ''), true);
  end if;

  ----------------------------------------------------------------------
  -- 12) Analytics + attention logs (COPY)
  ----------------------------------------------------------------------
  v_tmp_count := (select count(*) from public.resource_access where user_id = _source);
  c := public._jsonb_inc(c, ARRAY['resource_access','moved'], v_tmp_count);

  v_tmp_count := (select count(*) from public.search_analytics where user_id = _source);
  c := public._jsonb_inc(c, ARRAY['search_analytics','moved'], v_tmp_count);

  v_tmp_count := (select count(*) from public.user_attention_status_log where user_id = _source);
  c := public._jsonb_inc(c, ARRAY['attention_log','moved'], v_tmp_count);

  if not v_dry_run then
    insert into public.resource_access (resource_id, user_id, accessed_at, session_id)
    select resource_id, _dest, accessed_at, session_id
    from public.resource_access
    where user_id = _source;

    insert into public.search_analytics (query, results_count, user_id, searched_at, session_id)
    select query, results_count, _dest, searched_at, session_id
    from public.search_analytics
    where user_id = _source;

    insert into public.user_attention_status_log (
      user_id,
      manual_status,
      reason,
      prev_manual_status,
      prev_reason,
      changed_by,
      changed_at,
      change_source
    )
    select
      _dest,
      manual_status,
      reason,
      prev_manual_status,
      prev_reason,
      changed_by,
      changed_at,
      change_source
    from public.user_attention_status_log
    where user_id = _source;
  end if;

  ----------------------------------------------------------------------
  -- 13) Optional authorship reassignment (still MOVE semantics, opt-in)
  ----------------------------------------------------------------------
  if v_reassign_authorship then
    -- Count the references to be reassigned, including all three node fields.
    v_tmp_count := (select count(*) from public.content_nodes where owner_id = _source)
      + (select count(*) from public.content_nodes where created_by = _source)
      + (select count(*) from public.content_nodes where updated_by = _source)
      + (select count(*) from public.resources where created_by = _source)
      + (select count(*) from public.smart_docs where created_by = _source)
      + (select count(*) from public.tags where created_by = _source);
    c := public._jsonb_inc(c, ARRAY['authorship','reassigned'], v_tmp_count);
  end if;
  if not v_dry_run and v_reassign_authorship then
    update public.content_nodes set owner_id  = _dest where owner_id  = _source;
    update public.content_nodes set created_by = _dest where created_by = _source;
    update public.content_nodes set updated_by = _dest where updated_by = _source;
    update public.resources     set created_by = _dest where created_by = _source;
    update public.smart_docs    set created_by = _dest where created_by = _source;
    update public.tags          set created_by = _dest where created_by = _source;
  end if;

  ----------------------------------------------------------------------
  -- Finalize + log
  ----------------------------------------------------------------------
  c := c || jsonb_build_object('ghl_identity', jsonb_build_object('updated', 1));
  if not v_dry_run then
    -- Member scheduling still reads ghl_user_id as the contact ID. Staff
    -- accounts are refused above because the same legacy column means a staff
    -- user ID for coaches. Both member fields must agree after the copy.
    update public.profiles d set ghl_contact_id = v_destination_ghl_contact_id,
      ghl_user_id = v_destination_ghl_contact_id,
      introduced_at = least(d.introduced_at, s.introduced_at),
      attention_status_manual = coalesce(d.attention_status_manual, s.attention_status_manual),
      attention_status_manual_reason = case when d.attention_status_manual is null then s.attention_status_manual_reason else d.attention_status_manual_reason end,
      attention_status_updated_by = case when d.attention_status_manual is null then s.attention_status_updated_by else d.attention_status_updated_by end,
      attention_status_updated_at = case when d.attention_status_manual is null then s.attention_status_updated_at else d.attention_status_updated_at end
    from public.profiles s where s.id = _source and d.id = _dest;
    perform public.apply_user_attention_auto(_dest);
  end if;
  v_result := jsonb_build_object(
    'source', _source,
    'dest', _dest,
    'dry_run', v_dry_run,
    'counts', c,
    'request_id', v_request_id,
    'ghl', jsonb_build_object('destination_email', v_destination_email,
      'contact_id', v_destination_ghl_contact_id)
  );

  update public.user_merge_log
     set finished_at = now(),
         result_json = v_result
   where id = v_log_id;

  return v_result;
end;
$$;



-- The HTTP route supplies a service-role client after requireAdmin succeeds.
-- Both RPC entry points enforce the same database guard.
create or replace function public.transfer_user_data_admin(
  _source uuid, _dest uuid, _options jsonb default '{}'::jsonb
) returns jsonb
language sql security definer set search_path = pg_catalog, public
as $$
  select public.transfer_user_data(_source, _dest, coalesce(_options, '{}'::jsonb));
$$;

-- A versioned entry point prevents new application code from silently invoking
-- the old function that ignored verified GHL identities and request IDs.
create or replace function public.transfer_user_data_admin_v2(
  _source uuid, _dest uuid, _options jsonb default '{}'::jsonb
) returns jsonb
language sql security definer set search_path = pg_catalog, public
as $$
  select public.transfer_user_data(_source, _dest, coalesce(_options, '{}'::jsonb));
$$;

revoke all on function public.transfer_user_data(uuid, uuid, jsonb),
  public.transfer_user_data_admin(uuid, uuid, jsonb),
  public.transfer_user_data_admin_v2(uuid, uuid, jsonb) from public, anon, authenticated;
grant execute on function public.transfer_user_data(uuid, uuid, jsonb),
  public.transfer_user_data_admin(uuid, uuid, jsonb),
  public.transfer_user_data_admin_v2(uuid, uuid, jsonb) to service_role;

do $release_postconditions$
declare
  _name text;
  _role text;
  _function oid;
begin
  foreach _name in array array[
    'public.transfer_user_data(uuid,uuid,jsonb)',
    'public.transfer_user_data_admin(uuid,uuid,jsonb)',
    'public.transfer_user_data_admin_v2(uuid,uuid,jsonb)',
    'public.get_account_transfer_result_v2(uuid,uuid,jsonb)'
  ] loop
    _function := to_regprocedure(_name);
    if _function is null or not exists(select 1 from pg_proc where oid=_function and prosecdef) then
      raise exception 'Release verification failed: missing SECURITY DEFINER entry point %.',_name;
    end if;
    if not has_function_privilege('service_role',_function,'EXECUTE')
      or has_function_privilege('anon',_function,'EXECUTE')
      or has_function_privilege('authenticated',_function,'EXECUTE') then
      raise exception 'Release verification failed: entry point % is not service-role-only.',_name;
    end if;
  end loop;
  if not exists(select 1 from pg_class where oid='public.user_merge_log'::regclass and relrowsecurity) then
    raise exception 'Release verification failed: merge audit RLS is disabled.';
  end if;
  foreach _role in array array['anon','authenticated'] loop
    if has_table_privilege(_role,'public.user_merge_log','SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER')
      or has_sequence_privilege(_role,'public.user_merge_log_id_seq','USAGE,SELECT,UPDATE') then
      raise exception 'Release verification failed: browser role % still has merge audit privileges.',_role;
    end if;
  end loop;
  if not exists(select 1 from pg_index
    where indexrelid='public.user_merge_log_applied_request_id_idx'::regclass
      and indrelid='public.user_merge_log'::regclass and indisunique and indisvalid) then
    raise exception 'Release verification failed: request replay index is missing or invalid.';
  end if;
  foreach _name in array array['public.smart_doc_responses','public.smart_doc_response_values'] loop
    if not exists(select 1 from pg_trigger where tgrelid=_name::regclass
      and tgname='zzz_account_transfer_metadata' and not tgisinternal
      and tgenabled in ('O','A') and tgtype=23
      and tgfoid='public.restore_account_transfer_smart_doc_metadata()'::regprocedure) then
      raise exception 'Release verification failed: metadata preservation trigger is missing or incompatible on %.',_name;
    end if;
  end loop;
end;
$release_postconditions$;

-- Store the exact canonical SQL (including its own transaction wrapper), as
-- normal Supabase migration history, only after all postconditions succeed.
insert into supabase_migrations.schema_migrations(version,name,statements)
values ('20261008000000','complete_account_transfers',array[$migration_20261008000000$-- Complete member-account copies after the implementation-workspace release.
-- Apply only after the 2026-09-29 implementation migrations. The earlier transfer
-- migration is intentionally left unchanged because it has already been applied.
begin;

-- Replay records contain verified identities and may only be written/read by
-- the server. The original schema exposed this table to browser roles.
alter table public.user_merge_log enable row level security;
revoke all on table public.user_merge_log from public, anon, authenticated;
revoke all on sequence public.user_merge_log_id_seq from public, anon, authenticated;

-- Successful executions share one durable idempotency key. Dry-run audit entries
-- do not consume the key. Old logs without request_id are unaffected.
create unique index if not exists user_merge_log_applied_request_id_idx
  on public.user_merge_log ((options->>'request_id'))
  where not dry_run and options ? 'request_id';

-- A lost response must be recoverable even when GHL is down or the Auth email
-- subsequently changes. Only user-selected copy settings define the request;
-- verified GHL identity is derived server data retained in the saved result.
create or replace function public.get_account_transfer_result_v2(
  _source uuid, _dest uuid, _options jsonb default '{}'::jsonb
) returns jsonb
language plpgsql security definer set search_path = pg_catalog, public
as $$
declare
  request_id uuid;
  previous public.user_merge_log%rowtype;
  requested_options jsonb;
  previous_options jsonb;
begin
  if session_user not in ('postgres', 'supabase_admin')
    and coalesce(auth.role(), '') <> 'service_role' then
    raise exception 'Account transfers must use the admin server endpoint.' using errcode = '42501';
  end if;
  if jsonb_typeof(_options) is distinct from 'object' then
    raise exception 'Transfer options must be an object.' using errcode = '22023';
  end if;
  request_id := nullif(_options->>'request_id', '')::uuid;
  if request_id is null or coalesce((_options->>'dry_run')::boolean, true) then return null; end if;
  select * into previous from public.user_merge_log
  where not dry_run and options->>'request_id' = request_id::text;
  if not found then return null; end if;
  requested_options := jsonb_build_object(
    'reassign_authorship', coalesce((_options->>'reassign_authorship')::boolean, false),
    'smart_doc_conflict', coalesce(_options->>'smart_doc_conflict', 'keep_latest_submitted'),
    'progress_json_merge', coalesce(_options->>'progress_json_merge', 'prefer_dest'),
    'kpi_merge', coalesce(_options->>'kpi_merge', 'prefer_source'));
  previous_options := jsonb_build_object(
    'reassign_authorship', coalesce((previous.options->>'reassign_authorship')::boolean, false),
    'smart_doc_conflict', coalesce(previous.options->>'smart_doc_conflict', 'keep_latest_submitted'),
    'progress_json_merge', coalesce(previous.options->>'progress_json_merge', 'prefer_dest'),
    'kpi_merge', coalesce(previous.options->>'kpi_merge', 'prefer_source'));
  -- Profile deletion nulls the audit foreign keys; the immutable result retains
  -- the original identities so that a completed operation remains recoverable.
  if coalesce(previous.source_user_id, (previous.result_json->>'source')::uuid) is distinct from _source
    or coalesce(previous.dest_user_id, (previous.result_json->>'dest')::uuid) is distinct from _dest
    or requested_options is distinct from previous_options then
    raise exception 'This transfer request ID has already been used with different parameters.' using errcode = '22023';
  end if;
  if previous.finished_at is null or previous.result_json is null then
    raise exception 'This transfer request has no completed result.' using errcode = '55000';
  end if;
  return previous.result_json;
end;
$$;
revoke all on function public.get_account_transfer_result_v2(uuid, uuid, jsonb) from public, anon, authenticated;
grant execute on function public.get_account_transfer_result_v2(uuid, uuid, jsonb) to service_role;

-- Normal Smart Doc writes stamp the current actor/time. A history copy is not
-- a new edit, so restore metadata from the actual source row after those normal
-- BEFORE triggers, only within the trusted transfer's tightly scoped context.
create or replace function public.restore_account_transfer_smart_doc_metadata()
returns trigger language plpgsql set search_path = pg_catalog, public
as $$
declare
  context_text text := nullif(current_setting('reboot.account_transfer_smart_docs', true), '');
  context jsonb;
  source_user uuid;
  dest_user uuid;
  original record;
begin
  if context_text is null or (session_user not in ('postgres', 'supabase_admin')
    and coalesce(auth.role(), '') <> 'service_role') then
    return new;
  end if;
  context := context_text::jsonb;
  source_user := (context->>'source')::uuid;
  dest_user := (context->>'dest')::uuid;
  if source_user is null or dest_user is null or source_user = dest_user then
    raise exception 'Invalid Smart Doc transfer context.' using errcode = '22023';
  end if;
  if tg_table_name = 'smart_doc_responses' then
    if new.user_id <> dest_user then return new; end if;
    select r.created_by, r.updated_by, r.updated_at into original
    from public.smart_doc_responses r
    where r.user_id = source_user and r.content_block_id = new.content_block_id;
  else
    select value.created_by, value.updated_by, value.updated_at into original
    from public.smart_doc_responses destination
    join public.smart_doc_responses source
      on source.content_block_id = destination.content_block_id and source.user_id = source_user
    join public.smart_doc_response_values value
      on value.response_id = source.id and value.prompt_id = new.prompt_id
    where destination.id = new.response_id and destination.user_id = dest_user;
  end if;
  if not found then
    raise exception 'Source Smart Doc metadata was not found during transfer.' using errcode = '23514';
  end if;
  new.created_by := original.created_by;
  new.updated_by := original.updated_by;
  new.updated_at := original.updated_at;
  return new;
end;
$$;
revoke all on function public.restore_account_transfer_smart_doc_metadata()
  from public, anon, authenticated, service_role;
drop trigger if exists zzz_account_transfer_metadata on public.smart_doc_responses;
create trigger zzz_account_transfer_metadata before insert or update on public.smart_doc_responses
  for each row execute function public.restore_account_transfer_smart_doc_metadata();
drop trigger if exists zzz_account_transfer_metadata on public.smart_doc_response_values;
create trigger zzz_account_transfer_metadata before insert or update on public.smart_doc_response_values
  for each row execute function public.restore_account_transfer_smart_doc_metadata();

CREATE OR REPLACE FUNCTION "public"."transfer_user_data"("_source" "uuid", "_dest" "uuid", "_options" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_started_at timestamptz := now();
  v_dry_run boolean := coalesce((_options->>'dry_run')::boolean, true);
  v_reassign_authorship boolean := coalesce((_options->>'reassign_authorship')::boolean, false);
  v_sdoc_strategy text := coalesce((_options->>'smart_doc_conflict'), 'keep_latest_submitted');
  v_progress_json_strategy text := coalesce((_options->>'progress_json_merge'), 'prefer_dest');
  v_kpi_merge_strategy text := coalesce((_options->>'kpi_merge'), 'prefer_source');

  v_log_id bigint;
  v_result jsonb := '{}'::jsonb;
  rec record;
  v_new_note_id bigint;
  v_new_response_id bigint;
  v_existing_response public.smart_doc_responses%rowtype;
  v_use_source_response boolean;
  v_new_review_id bigint;
  v_new_step_id bigint;
  v_new_session_id uuid;
  v_note_map jsonb := '{}'::jsonb;
  v_step_map jsonb := '{}'::jsonb;
  v_session_map jsonb := '{}'::jsonb;
  v_source_note_ids bigint[];
  v_source_session_ids uuid[];
  v_snapshot jsonb;
  v_step record;
  v_tmp_count bigint;
  v_course_visibility_count bigint;
  v_achievements_merged_count bigint;
  v_request_id uuid;
  v_destination_email text;
  v_destination_ghl_contact_id text;
  v_actual_email text;
  v_previous_smart_doc_context text;
  v_coach_seen_rows jsonb;
  v_coach_active_keys jsonb;
  v_coach_row_key text;
  v_coach_pair_key text;
  v_assistant_seen_rows jsonb;
  v_assistant_row_key text;

  c jsonb := '{
    "coaching_notes": {"moved":0},
    "action_steps": {"linked":0},
    "comments": {"linked":0},
    "wins": {"moved":0},
    "kpi_records": {"moved":0,"merged":0},
    "kpi_values": {"upserted":0},
    "attendance": {"moved":0,"merged":0},
    "achievements": {"moved":0,"merged":0,"skipped_dupe":0},
    "roles": {"added":0,"removed_source":0},
    "course_visibility": {"added":0,"removed_source":0},
    "user_coaches": {"moved":0,"merged":0},
    "partnership_users": {"moved":0,"skipped_dupe":0},
    "progress": {"moved":0,"merged":0},
    "smart_docs": {"reassigned":0,"drafted_older":0},
    "resource_access": {"moved":0},
    "search_analytics": {"moved":0},
    "attention_log": {"moved":0},
    "authorship": {"reassigned":0}
  }'::jsonb;
begin
  -- Only the guarded server route can supply an email-verified GHL contact.
  -- SECURITY DEFINER changes current_user; use session_user/JWT role instead.
  if session_user not in ('postgres', 'supabase_admin')
     and coalesce(auth.role(), '') <> 'service_role' then
    raise exception 'Account transfers must use the admin server endpoint.' using errcode = '42501';
  end if;
  if jsonb_typeof(_options) is distinct from 'object' then
    raise exception 'Transfer options must be an object.' using errcode = '22023';
  end if;
  -- Guardrails
  if _source is null or _dest is null or _source = _dest then
    raise exception 'Invalid source/dest';
  end if;

  -- Serialize copies sharing either account, regardless of transfer direction.
  perform pg_advisory_xact_lock(hashtextextended('account-transfer:' || least(_source::text, _dest::text), 0));
  perform pg_advisory_xact_lock(hashtextextended('account-transfer:' || greatest(_source::text, _dest::text), 0));

  v_request_id := nullif(_options->>'request_id', '')::uuid;
  if not v_dry_run and v_request_id is null then
    raise exception 'A transfer request ID is required.' using errcode = '22023';
  end if;
  if v_request_id is not null then
    _options := jsonb_set(_options, '{request_id}', to_jsonb(v_request_id::text));
    perform pg_advisory_xact_lock(hashtextextended('account-transfer-request:' || v_request_id::text, 0));
    if not v_dry_run then
      v_result := public.get_account_transfer_result_v2(_source, _dest, _options);
      if v_result is not null then return v_result; end if;
    end if;
  end if;

  perform 1 from public.profiles where id = _source;
  if not found then raise exception 'Source profile % not found', _source; end if;
  perform 1 from public.profiles where id = _dest;
  if not found then raise exception 'Destination profile % not found', _dest; end if;

  v_destination_email := lower(btrim(_options->>'destination_email'));
  v_destination_ghl_contact_id := nullif(btrim(_options->>'destination_ghl_contact_id'), '');
  if coalesce(v_destination_email, '') = '' or v_destination_ghl_contact_id is null then
    raise exception 'A verified destination email and GHL contact are required.' using errcode = '22023';
  end if;
  -- Keep an Auth email change from racing the server lookup and profile update.
  select lower(btrim(email)) into v_actual_email from auth.users where id = _dest for share;
  if v_actual_email is distinct from v_destination_email then
    raise exception 'The destination email changed. Preview the transfer again.' using errcode = '22023';
  end if;

  if v_kpi_merge_strategy not in ('prefer_source', 'skip', 'none')
    or v_sdoc_strategy not in ('keep_latest_submitted', 'keep_source', 'keep_dest')
    or v_progress_json_strategy not in ('prefer_dest', 'prefer_source', 'deep_merge') then
    raise exception 'Unsupported account transfer strategy.' using errcode = '22023';
  end if;

  if exists (select 1 from public.user_roles ur join public.roles r on r.id = ur.role_id
    where ur.user_id in (_source, _dest) and r.code in ('coach', 'implementation_coach')) then
    raise exception 'Staff accounts cannot be copied with the member-account transfer. Coach calendars and staff IDs need a separate migration.' using errcode = '23514';
  end if;
  if exists (select 1 from public.user_roles ur join public.roles r on r.id = ur.role_id
      where ur.user_id = _source and r.code = 'past_member')
    and exists (select 1 from public.get_current_member_ids() current_member where current_member.user_id = _dest) then
    raise exception 'The source is a past member but the destination is current. Resolve membership status before transferring.' using errcode = '23514';
  end if;
  if exists (select 1 from public.user_roles ur join public.roles r on r.id = ur.role_id
      where ur.user_id = _dest and r.code = 'past_member')
    and exists (select 1 from public.get_current_member_ids() current_member where current_member.user_id = _source) then
    raise exception 'The destination is a past member but the source is current. Resolve membership status before transferring.' using errcode = '23514';
  end if;

  -- Base-table triggers redirect writes to the partnership owner. Refuse to
  -- write a third person's history, even when the UI chose this destination.
  if public.canonical_owner_for(_dest, 'notes') <> _dest
    or public.canonical_owner_for(_dest, 'attendance') <> _dest
    or (v_kpi_merge_strategy not in ('skip', 'none') and public.canonical_owner_for(_dest, 'kpis') <> _dest) then
    raise exception 'The destination shares account data owned by a partner. Resolve partnership ownership before transferring.' using errcode = '23514';
  end if;
  if public.canonical_owner_for(_source, 'notes') <> _source
    or public.canonical_owner_for(_source, 'attendance') <> _source
    or (v_kpi_merge_strategy not in ('skip', 'none') and public.canonical_owner_for(_source, 'kpis') <> _source) then
    raise exception 'The source shares account data owned by a partner. Resolve partnership ownership before transferring.' using errcode = '23514';
  end if;
  if exists (
    select 1 from public.partnerships p
    join public.partnership_users source_member on source_member.partnership_id = p.id and source_member.user_id = _source
    where p.is_active and (p.shared_notes or p.shared_attendance or (p.shared_kpis and v_kpi_merge_strategy not in ('skip', 'none')))
      and not exists (select 1 from public.partnership_users d where d.partnership_id = p.id and d.user_id = _dest)
  ) then
    raise exception 'Adding the destination to a shared partnership would redirect copied account data. Resolve partnership ownership before transferring.' using errcode = '23514';
  end if;

  -- One snapshot of the graph also includes legacy shared notes explicitly
  -- referenced by this member's review, training assignment or workspace.
  select coalesce(array_agg(n.id), '{}'::bigint[]) into v_source_note_ids
  from public.coaching_notes_base n
  where n.user_id = _source
    or exists (select 1 from public.business_reviews r where r.user_id = _source and r.coaching_note_id = n.id)
    or exists (select 1 from public.implementation_meeting_sessions s where s.user_id = _source and s.note_id = n.id)
    or exists (select 1 from public.user_training_assignments a where a.user_id = _source and a.coaching_note_id = n.id);
  -- Workspace mutations also lock their note row, so no half-saved history can
  -- enter the copy. Child changes are otherwise covered by the same transaction.
  perform 1 from public.coaching_notes_base where id = any(v_source_note_ids) order by id for update;
  select coalesce(array_agg(id), '{}'::uuid[]) into v_source_session_ids
  from public.implementation_meeting_sessions where user_id = _source;
  if exists (
    select 1 from public.implementation_meeting_sessions s
    cross join lateral jsonb_array_elements(s.progress_snapshot) item
    where s.id = any(v_source_session_ids) and (
      jsonb_typeof(item) is distinct from 'object'
      or jsonb_typeof(item->'actionStepId') is distinct from 'number'
      or not exists (select 1 from public.coaching_note_action_steps a
        where a.id::text = item->>'actionStepId' and a.coaching_note_id = s.note_id)
    )
  ) or exists (
    select 1 from public.implementation_session_actions sa
    join public.implementation_meeting_sessions s on s.id = sa.session_id
    join public.coaching_note_action_steps a on a.id = sa.action_step_id
    where s.id = any(v_source_session_ids) and a.coaching_note_id <> s.note_id
  ) then
    raise exception 'Implementation history references an action outside its copied coaching cycle.' using errcode = '23514';
  end if;
  if exists (
    select 1 from public.implementation_meeting_sessions s
    join public.implementation_meeting_sessions d on d.user_id = _dest and d.meeting_id = s.meeting_id
    where s.id = any(v_source_session_ids)
  ) then
    raise exception 'The destination already has implementation history for a source meeting. Resolve the duplicate meeting before transferring.' using errcode = '23505';
  end if;
  if exists (select 1 from public.user_training_assignments a
    join public.content_nodes n on n.id = a.course_node_id
    where a.user_id = _source and (n.node_type::text <> 'course' or n.state::text <> 'published')) then
    raise exception 'Source training history references an unpublished course. Resolve that assignment before transferring.' using errcode = '23514';
  end if;
  if exists (select 1 from public.user_assistants where user_id = _source and assistant_id = _dest) then
    raise exception 'The destination is an assistant on the source account. Resolve the assignment before transferring.' using errcode = '23514';
  end if;
  if exists (select 1 from public.user_assistants s join public.user_assistants d
    on d.user_id = _dest and d.is_active and (d.ended_at is null or d.ended_at > now())
    where s.user_id = _source and s.is_active and (s.ended_at is null or s.ended_at > now())
      and s.assistant_id <> d.assistant_id) then
    raise exception 'The two accounts have different active assistants. Resolve the assignments before transferring.' using errcode = '23514';
  end if;
  if exists (select 1 from public.ninety_day_cycle_users s
    join public.ninety_day_cycle_users d on d.user_id = _dest
    where s.user_id = _source and (
      (s.ended_at is null and d.ended_at is null and s.cycle_id <> d.cycle_id)
      or (s.cycle_id = d.cycle_id and (s.ended_at is distinct from d.ended_at or s.outcome is distinct from d.outcome))
    )) then
    raise exception 'The accounts have conflicting 90-day enrolments. Resolve the enrolments before transferring.' using errcode = '23514';
  end if;
  if exists (select 1 from public.member_pauses s join public.member_pauses d
    on d.user_id = _dest and d.ended_at is null
    where s.user_id = _source and s.ended_at is null
      and (s.started_at, s.reason, s.started_by) is distinct from (d.started_at, d.reason, d.started_by)) then
    raise exception 'The accounts have different open pauses. Resolve the pauses before transferring.' using errcode = '23514';
  end if;

  insert into public.user_merge_log (source_user_id, dest_user_id, started_at, dry_run, options)
  values (_source, _dest, v_started_at, v_dry_run, _options)
  returning id into v_log_id;

  -- Training and completed-action triggers may grant access/achievements before
  -- their copy sections. Report the pre-transfer comparison consistently.
  select count(*) into v_course_visibility_count from public.user_course_visibility s
  where s.user_id = _source and not exists (
    select 1 from public.user_course_visibility d where d.user_id = _dest and d.course_node_id = s.course_node_id);
  select count(*) into v_achievements_merged_count from public.user_achievements s
  where s.user_id = _source and exists (
    select 1 from public.user_achievements d where d.user_id = _dest and d.achievement_id = s.achievement_id);

  ----------------------------------------------------------------------
  -- 1) Coaching notes + action steps + comments (COPY)
  ----------------------------------------------------------------------
  v_tmp_count := (select count(*) from public.coaching_notes_base n
    where n.id = any(v_source_note_ids));
  c := public._jsonb_inc(c, ARRAY['coaching_notes','moved'], v_tmp_count);

  v_tmp_count := (
    select count(*)
    from public.coaching_note_action_steps s
    join public.coaching_notes_base n on s.coaching_note_id = n.id
    where n.id = any(v_source_note_ids)
  );
  c := public._jsonb_inc(c, ARRAY['action_steps','linked'], v_tmp_count);

  v_tmp_count := (
    select count(*)
    from public.coaching_note_comments s
    join public.coaching_notes_base n on s.coaching_note_id = n.id
    where n.id = any(v_source_note_ids)
  );
  c := public._jsonb_inc(c, ARRAY['comments','linked'], v_tmp_count);

  if not v_dry_run then
    for rec in
      select n.* from public.coaching_notes_base n
      where n.id = any(v_source_note_ids)
    loop
      insert into public.coaching_notes_base (
        user_id, coach_id, created_at, updated_at, m2_meeting_id, deleted_at, deleted_by
      ) values (
        _dest, rec.coach_id, rec.created_at, rec.updated_at, rec.m2_meeting_id,
        rec.deleted_at, rec.deleted_by
      )
      returning id into v_new_note_id;

      v_note_map := v_note_map || jsonb_build_object(rec.id::text, v_new_note_id);

      for v_step in
        select * from public.coaching_note_action_steps where coaching_note_id = rec.id
      loop
        insert into public.coaching_note_action_steps (
          coaching_note_id, label, library_item_id, status, created_at, updated_at
        ) values (
          v_new_note_id, v_step.label, v_step.library_item_id, v_step.status,
          v_step.created_at, v_step.updated_at
        ) returning id into v_new_step_id;
        v_step_map := v_step_map || jsonb_build_object(v_step.id::text, v_new_step_id);
      end loop;

      insert into public.coaching_note_comments (
        coaching_note_id, author_id, body, created_at
      )
      select
        v_new_note_id,
        cmt.author_id,
        cmt.body,
        cmt.created_at
      from public.coaching_note_comments cmt
      where cmt.coaching_note_id = rec.id;
    end loop;
  end if;

  ----------------------------------------------------------------------
  -- 1b) Business Reviews and all review-owned data (COPY).
  -- Historical JSON snapshots retain their original IDs as audit evidence.
  -- A meeting owns at most one review, so the copy cannot claim its meeting_id.
  -- The copied coaching note retains m2_meeting_id as the meeting reference.
  ----------------------------------------------------------------------
  c := c || jsonb_build_object('business_reviews', jsonb_build_object(
    'copied', (select count(*) from public.business_reviews where user_id = _source),
    'meeting_links_not_copied', (select count(*) from public.business_reviews
      where user_id = _source and meeting_id is not null)
  ));

  for rec in
    select * from (values
      ('business_review_focus_values'),
      ('business_review_preparation_responses'),
      ('business_review_additional_scorecards'),
      ('business_review_system_ratings'),
      ('business_review_system_priorities'),
      ('system_scorecard_version_migrations')
    ) as review_tables(table_name)
  loop
    execute format(
      'select count(*) from public.%I child join public.business_reviews review
       on review.id = child.business_review_id where review.user_id = $1', rec.table_name
    ) into v_tmp_count using _source;
    c := c || jsonb_build_object(rec.table_name, jsonb_build_object('copied', v_tmp_count));
  end loop;

  if not v_dry_run then
    for rec in select * from public.business_reviews where user_id = _source order by id
    loop
      insert into public.business_reviews (
        user_id, coach_id, coaching_note_id, focus_finder_template_key,
        review_date, status, completed_at, completed_by, created_at, updated_at,
        system_scorecard_template_key, meeting_id
      ) values (
        _dest, rec.coach_id, (v_note_map->>rec.coaching_note_id::text)::bigint,
        rec.focus_finder_template_key, rec.review_date, rec.status,
        rec.completed_at, rec.completed_by, rec.created_at, rec.updated_at,
        rec.system_scorecard_template_key, null
      ) returning id into v_new_review_id;

      insert into public.business_review_focus_values (
        business_review_id, template_key, dimension_id, value, updated_by, created_at, updated_at
      ) select v_new_review_id, template_key, dimension_id, value, updated_by, created_at, updated_at
        from public.business_review_focus_values where business_review_id = rec.id;

      insert into public.business_review_preparation_responses (
        business_review_id, business_forward_wins, personal_forward_wins,
        greatest_business_challenge, greatest_personal_challenge, desired_call_outcome,
        topics_to_discuss, business_rating, personal_rating, submitted_at, updated_at
      ) select v_new_review_id, business_forward_wins, personal_forward_wins,
          greatest_business_challenge, greatest_personal_challenge, desired_call_outcome,
          topics_to_discuss, business_rating, personal_rating, submitted_at, updated_at
        from public.business_review_preparation_responses where business_review_id = rec.id;

      -- Register the extra Foundation template before its ratings are validated.
      insert into public.business_review_additional_scorecards (
        business_review_id, template_key, assigned_by, created_at
      ) select v_new_review_id, template_key, assigned_by, created_at
        from public.business_review_additional_scorecards where business_review_id = rec.id;

      insert into public.business_review_system_ratings (
        business_review_id, template_key, system_id, status, reviewed_at,
        reviewed_by, updated_by, created_at, updated_at
      ) select v_new_review_id, template_key, system_id, status, reviewed_at,
          reviewed_by, updated_by, created_at, updated_at
        from public.business_review_system_ratings where business_review_id = rec.id;

      insert into public.business_review_system_priorities (
        business_review_id, system_id, position, action_step_id, starting_status, selected_at, selected_by
      ) select v_new_review_id, system_id, position,
          (v_step_map->>action_step_id::text)::bigint, starting_status, selected_at, selected_by
        from public.business_review_system_priorities where business_review_id = rec.id;

      insert into public.system_scorecard_version_migrations (
        business_review_id, from_template_key, to_template_key, migrated_by,
        resolution, previous_snapshot, created_at
      ) select v_new_review_id, from_template_key, to_template_key, migrated_by,
          resolution, previous_snapshot, created_at
        from public.system_scorecard_version_migrations where business_review_id = rec.id;
    end loop;
  end if;

  ----------------------------------------------------------------------
  -- 1c) Implementation workspaces and standalone coaching notes (COPY).
  -- Guide step UUIDs and meeting IDs are immutable shared references. Action
  -- IDs in snapshots are live links and must follow the copied action graph.
  ----------------------------------------------------------------------
  c := c || jsonb_build_object(
    'implementation_action_checklists', jsonb_build_object('copied', (
      select count(*) from public.implementation_action_checklists a
      join public.coaching_note_action_steps s on s.id = a.action_step_id
      where s.coaching_note_id = any(v_source_note_ids))),
    'implementation_meeting_sessions', jsonb_build_object('copied', cardinality(v_source_session_ids)),
    'implementation_session_actions', jsonb_build_object('copied', (
      select count(*) from public.implementation_session_actions where session_id = any(v_source_session_ids))),
    'implementation_step_notes', jsonb_build_object('copied', (
      select count(*) from public.implementation_step_notes where session_id = any(v_source_session_ids))),
    'implementation_step_events', jsonb_build_object('copied', (
      select count(*) from public.implementation_step_events where session_id = any(v_source_session_ids))),
    'general_coaching_notes', jsonb_build_object('copied', (
      select count(*) from public.general_coaching_notes where user_id = _source))
  );

  if not v_dry_run then
    insert into public.implementation_action_checklists (
      action_step_id, guide_id, guide_revision, steps, progress, created_at, updated_at
    ) select (v_step_map->>a.action_step_id::text)::bigint,
        a.guide_id, a.guide_revision, a.steps, a.progress, a.created_at, a.updated_at
      from public.implementation_action_checklists a
      join public.coaching_note_action_steps s on s.id = a.action_step_id
      where s.coaching_note_id = any(v_source_note_ids);

    for rec in select * from public.implementation_meeting_sessions
      where id = any(v_source_session_ids) order by started_at, id
    loop
      select coalesce(jsonb_agg(
        jsonb_set(item.value, '{actionStepId}', v_step_map->(item.value->>'actionStepId'))
        order by item.ordinality), '[]'::jsonb) into v_snapshot
      from jsonb_array_elements(rec.progress_snapshot) with ordinality item(value, ordinality);

      insert into public.implementation_meeting_sessions (
        note_id, meeting_id, user_id, status, revision, started_at, updated_at,
        completed_at, updated_by, notes, commitments, progress_snapshot,
        notes_written_at, notes_author_id, notes_updated_at, notes_updated_by, next_meeting_booked
      ) values (
        (v_note_map->>rec.note_id::text)::bigint, rec.meeting_id, _dest,
        rec.status, rec.revision, rec.started_at, rec.updated_at, rec.completed_at,
        rec.updated_by, rec.notes, rec.commitments, v_snapshot, rec.notes_written_at,
        rec.notes_author_id, rec.notes_updated_at, rec.notes_updated_by, rec.next_meeting_booked
      ) returning id into v_new_session_id;
      v_session_map := v_session_map || jsonb_build_object(rec.id::text, v_new_session_id);
    end loop;

    insert into public.implementation_session_actions (session_id, action_step_id)
    select (v_session_map->>session_id::text)::uuid, (v_step_map->>action_step_id::text)::bigint
    from public.implementation_session_actions where session_id = any(v_source_session_ids);

    insert into public.implementation_step_notes (
      session_id, action_step_id, step_id, body, author_id, created_at
    ) select (v_session_map->>session_id::text)::uuid, (v_step_map->>action_step_id::text)::bigint,
        step_id, body, author_id, created_at
      from public.implementation_step_notes where session_id = any(v_source_session_ids);

    insert into public.implementation_step_events (
      session_id, action_step_id, step_id, completed, created_by, created_at
    ) select (v_session_map->>session_id::text)::uuid, (v_step_map->>action_step_id::text)::bigint,
        step_id, completed, created_by, created_at
      from public.implementation_step_events where session_id = any(v_source_session_ids);

    insert into public.general_coaching_notes (id, user_id, author_id, body, created_at)
    select gen_random_uuid(), _dest, author_id, body, created_at
    from public.general_coaching_notes where user_id = _source;
  end if;

  ----------------------------------------------------------------------
  -- 1d) Other member coaching/lifecycle records introduced since the original
  -- transfer. Attribution remains the original author, never the copying admin.
  ----------------------------------------------------------------------
  c := c || jsonb_build_object(
    'coaching_private_notes', jsonb_build_object('copied', (
      select count(*) from public.coaching_private_notes where user_id = _source)),
    'user_training_assignments', jsonb_build_object('copied', (
      select count(*) from public.user_training_assignments where user_id = _source)),
    'member_pauses', jsonb_build_object('copied', (
      select count(*) from public.member_pauses s where s.user_id = _source and not exists (
        select 1 from public.member_pauses d where d.user_id = _dest
          and (d.started_at, d.ended_at, d.reason, d.started_by, d.ended_by)
            is not distinct from (s.started_at, s.ended_at, s.reason, s.started_by, s.ended_by)))),
    'ninety_day_cycle_users', jsonb_build_object(
      'copied', (select count(*) from public.ninety_day_cycle_users s where s.user_id = _source
        and not exists (select 1 from public.ninety_day_cycle_users d where d.user_id = _dest and d.cycle_id = s.cycle_id)),
      'merged', (select count(*) from public.ninety_day_cycle_users s where s.user_id = _source
        and exists (select 1 from public.ninety_day_cycle_users d where d.user_id = _dest and d.cycle_id = s.cycle_id))),
    'member_home_preferences', jsonb_build_object('copied', (
      select count(*) from public.member_home_preferences where user_id = _source
        and not exists (select 1 from public.member_home_preferences where user_id = _dest))),
    'user_assistants', jsonb_build_object('copied', 0, 'merged', 0, 'skipped_dupe', 0)
  );
  if not v_dry_run then
    insert into public.coaching_private_notes (user_id, author_id, body, created_at)
    select _dest, author_id, body, created_at from public.coaching_private_notes where user_id = _source;

    insert into public.user_training_assignments (
      user_id, course_node_id, coaching_note_id, assigned_by, assigned_at,
      context_label, due_at, ended_at, ended_by
    ) select _dest, course_node_id, (v_note_map->>coaching_note_id::text)::bigint,
        assigned_by, assigned_at, context_label, due_at, ended_at, ended_by
      from public.user_training_assignments where user_id = _source;

    insert into public.member_pauses (user_id, started_at, ended_at, reason, started_by, ended_by)
    select _dest, s.started_at, s.ended_at, s.reason, s.started_by, s.ended_by
    from public.member_pauses s where s.user_id = _source and not exists (
      select 1 from public.member_pauses d where d.user_id = _dest
        and (d.started_at, d.ended_at, d.reason, d.started_by, d.ended_by)
          is not distinct from (s.started_at, s.ended_at, s.reason, s.started_by, s.ended_by));

    insert into public.ninety_day_cycle_users (cycle_id, user_id, enrolled_at, ended_at, outcome)
    select cycle_id, _dest, enrolled_at, ended_at, outcome
    from public.ninety_day_cycle_users where user_id = _source
    on conflict (cycle_id, user_id) do update
      set enrolled_at = least(public.ninety_day_cycle_users.enrolled_at, excluded.enrolled_at);

    insert into public.member_home_preferences (user_id, default_home)
    select _dest, default_home from public.member_home_preferences where user_id = _source
    on conflict (user_id) do nothing;
  end if;

  select coalesce(jsonb_object_agg(jsonb_build_array(assistant_id,
      is_active and (ended_at is null or ended_at > now()), assigned_at, ended_at, assigned_by, notes)::text, true), '{}'::jsonb)
    into v_assistant_seen_rows from public.user_assistants where user_id = _dest;
  for rec in select * from public.user_assistants where user_id = _source order by id
  loop
    v_assistant_row_key := jsonb_build_array(rec.assistant_id,
      rec.is_active and (rec.ended_at is null or rec.ended_at > now()),
      rec.assigned_at, rec.ended_at, rec.assigned_by, rec.notes)::text;
    if v_assistant_seen_rows ? v_assistant_row_key then
      c := public._jsonb_inc(c, array['user_assistants','skipped_dupe'], 1);
    elsif rec.is_active and (rec.ended_at is null or rec.ended_at > now()) and exists (select 1 from public.user_assistants d
      where d.user_id = _dest and d.assistant_id = rec.assistant_id and d.is_active
        and (d.ended_at is null or d.ended_at > now())) then
      c := public._jsonb_inc(c, array['user_assistants','merged'], 1);
      if not v_dry_run then
        update public.user_assistants d set
          assigned_at = least(d.assigned_at, rec.assigned_at),
          ended_at = case when d.ended_at is null or rec.ended_at is null then null else greatest(d.ended_at, rec.ended_at) end,
          notes = case when d.notes is null then rec.notes when rec.notes is null or d.notes = rec.notes then d.notes
            else d.notes || E'\n\n' || rec.notes end
        where d.user_id = _dest and d.assistant_id = rec.assistant_id and d.is_active
          and (d.ended_at is null or d.ended_at > now());
      end if;
    else
      c := public._jsonb_inc(c, array['user_assistants','copied'], 1);
      if not v_dry_run then
        -- The active-pair index checks the flag alone. Clear obsolete flags
        -- without changing historical dates so a current assignment can coexist.
        update public.user_assistants set is_active = false
        where user_id = _dest and assistant_id = rec.assistant_id and is_active and ended_at <= now()
          and rec.is_active and (rec.ended_at is null or rec.ended_at > now());
        insert into public.user_assistants (user_id, assistant_id, is_active, assigned_at, ended_at, assigned_by, notes)
        values (_dest, rec.assistant_id, rec.is_active and (rec.ended_at is null or rec.ended_at > now()),
          rec.assigned_at, rec.ended_at, rec.assigned_by, rec.notes);
      end if;
    end if;
    v_assistant_seen_rows := v_assistant_seen_rows || jsonb_build_object(v_assistant_row_key, true);
  end loop;

  ----------------------------------------------------------------------
  -- 2) Wins (COPY)
  ----------------------------------------------------------------------
  v_tmp_count := (select count(*) from public.wins where user_id = _source);
  c := public._jsonb_inc(c, ARRAY['wins','moved'], v_tmp_count);

  if not v_dry_run then
    insert into public.wins (user_id, added_by, body, created_at)
    select _dest, added_by, body, created_at
    from public.wins
    where user_id = _source;
  end if;

  ----------------------------------------------------------------------
  -- 3) KPI: preserve the explicit source-replaces-destination strategy.
  -- Counts describe actual planned writes and disclose exactly what is replaced.
  ----------------------------------------------------------------------
  c := jsonb_set(c, '{kpi_records}', jsonb_build_object(
    'moved', case when v_kpi_merge_strategy in ('skip','none') then 0
      else (select count(*) from public.monthly_kpi_records_base where user_id = _source) end,
    'skipped', case when v_kpi_merge_strategy in ('skip','none')
      then (select count(*) from public.monthly_kpi_records_base where user_id = _source) else 0 end,
    'destination_records_replaced', case when v_kpi_merge_strategy in ('skip','none') then 0
      else (select count(*) from public.monthly_kpi_records_base where user_id = _dest) end));
  c := jsonb_set(c, '{kpi_values}', jsonb_build_object(
    'upserted', case when v_kpi_merge_strategy in ('skip','none') then 0
      else (select count(*) from public.monthly_kpi_values v join public.monthly_kpi_records_base r on r.id=v.monthly_kpi_record_id where r.user_id=_source) end,
    'skipped', case when v_kpi_merge_strategy in ('skip','none')
      then (select count(*) from public.monthly_kpi_values v join public.monthly_kpi_records_base r on r.id=v.monthly_kpi_record_id where r.user_id=_source) else 0 end,
    'destination_values_replaced', case when v_kpi_merge_strategy in ('skip','none') then 0
      else (select count(*) from public.monthly_kpi_values v join public.monthly_kpi_records_base r on r.id=v.monthly_kpi_record_id where r.user_id=_dest) end));
  if not v_dry_run and v_kpi_merge_strategy not in ('skip', 'none') then
    lock table public.monthly_kpi_records_base, public.monthly_kpi_values in share row exclusive mode;
    delete from public.monthly_kpi_values v using public.monthly_kpi_records_base r
      where v.monthly_kpi_record_id = r.id and r.user_id = _dest;
    delete from public.monthly_kpi_records_base where user_id = _dest;
    insert into public.monthly_kpi_records_base (
      user_id, period_start_date, created_at, last_updated_at, last_updated_by
    ) select _dest, period_start_date, created_at, last_updated_at, last_updated_by
      from public.monthly_kpi_records_base where user_id = _source;
    insert into public.monthly_kpi_values (monthly_kpi_record_id, metric_type_id, value)
    select d.id, v.metric_type_id, v.value from public.monthly_kpi_values v
      join public.monthly_kpi_records_base s on s.id = v.monthly_kpi_record_id and s.user_id = _source
      join public.monthly_kpi_records_base d on d.user_id = _dest and d.period_start_date = s.period_start_date;
  end if;

  ----------------------------------------------------------------------
  -- 4) Attendance (COPY)
  ----------------------------------------------------------------------
  v_tmp_count := (select count(*) from public.meeting_attendance_base where user_id = _source);
  c := public._jsonb_inc(c, ARRAY['attendance','moved'], v_tmp_count);

  v_tmp_count := (
    select count(*)
    from public.meeting_attendance_base s
    join public.meeting_attendance_base d
      on d.meeting_id = s.meeting_id
     and d.user_id = _dest
    where s.user_id = _source
  );
  c := public._jsonb_inc(c, ARRAY['attendance','merged'], v_tmp_count);

  if not v_dry_run then
    insert into public.meeting_attendance_base (meeting_id, user_id, attended, created_at, updated_at)
    select meeting_id, _dest, attended, created_at, updated_at
    from public.meeting_attendance_base
    where user_id = _source
    on conflict (meeting_id, user_id)
    do update set
      attended   = (excluded.attended or public.meeting_attendance_base.attended),
      created_at = least(public.meeting_attendance_base.created_at, excluded.created_at),
      updated_at = greatest(public.meeting_attendance_base.updated_at, excluded.updated_at);
  end if;

  ----------------------------------------------------------------------
  -- 5) Achievements (COPY)
  ----------------------------------------------------------------------
  v_tmp_count := (select count(*) from public.user_achievements where user_id = _source);
  c := public._jsonb_inc(c, ARRAY['achievements','moved'], v_tmp_count);

  c := public._jsonb_inc(c, ARRAY['achievements','merged'], v_achievements_merged_count);

  if not v_dry_run then
    with overlap as (
      select s.id as s_id, d.id as d_id, s.achieved_at as s_at, d.achieved_at as d_at,
             s.awarded_via as s_via, d.awarded_via as d_via
      from public.user_achievements s
      join public.user_achievements d
        on d.user_id = _dest
       and s.user_id = _source
       and d.achievement_id = s.achievement_id
    )
    update public.user_achievements d
       set achieved_at = least(d.achieved_at, o.s_at),
           awarded_via = case
                           when d.awarded_via = o.s_via then d.awarded_via
                           else 'reconcile'
                         end
      from overlap o
     where d.id = o.d_id;

    insert into public.user_achievements (user_id, achievement_id, achieved_at, awarded_via)
    select _dest, s.achievement_id, s.achieved_at, s.awarded_via
    from public.user_achievements s
    where s.user_id = _source
      and not exists (
        select 1
        from public.user_achievements d
        where d.user_id = _dest
          and d.achievement_id = s.achievement_id
      );
  end if;

  ----------------------------------------------------------------------
  -- 6) Roles (COPY)
  ----------------------------------------------------------------------
  v_tmp_count := (
    select count(*)
    from public.user_roles s
    where s.user_id = _source
      and not exists (
        select 1
        from public.user_roles d
        where d.user_id = _dest
          and d.role_id = s.role_id
      )
  );
  c := public._jsonb_inc(c, ARRAY['roles','added'], v_tmp_count);

  if not v_dry_run then
    insert into public.user_roles (user_id, role_id)
    select _dest, role_id
    from public.user_roles s
    where s.user_id = _source
      and not exists (
        select 1
        from public.user_roles d
        where d.user_id = _dest
          and d.role_id = s.role_id
      );
  end if;

  ----------------------------------------------------------------------
  -- 7) Course visibility (COPY)
  ----------------------------------------------------------------------
  c := public._jsonb_inc(c, ARRAY['course_visibility','added'], v_course_visibility_count);

  if not v_dry_run then
    insert into public.user_course_visibility (user_id, course_node_id)
    select _dest, course_node_id
    from public.user_course_visibility s
    where s.user_id = _source
      and not exists (
        select 1
        from public.user_course_visibility d
        where d.user_id = _dest
          and d.course_node_id = s.course_node_id
      );
  end if;

  ----------------------------------------------------------------------
  -- 8) Coach assignments: preserve separate historical intervals; merge only
  -- currently active assignments for the same coach/course/relationship.
  -- Track planned rows in both modes so previews also count repeated source
  -- assignments correctly before any destination writes exist.
  ----------------------------------------------------------------------
  c := jsonb_set(c, '{user_coaches}', jsonb_build_object('moved', 0, 'merged', 0, 'skipped_dupe', 0));
  select coalesce(jsonb_object_agg(jsonb_build_array(coach_id, course_id, relationship_type,
      is_active, assigned_at, ended_at)::text, true), '{}'::jsonb)
    into v_coach_seen_rows from public.user_coaches where user_id = _dest;
  select coalesce(jsonb_object_agg(jsonb_build_array(coach_id, course_id, relationship_type)::text, true), '{}'::jsonb)
    into v_coach_active_keys from public.user_coaches
    where user_id = _dest and is_active and (ended_at is null or ended_at > now());
  for rec in select * from public.user_coaches where user_id = _source order by assigned_at, id
  loop
    v_coach_row_key := jsonb_build_array(rec.coach_id, rec.course_id, rec.relationship_type,
      rec.is_active, rec.assigned_at, rec.ended_at)::text;
    v_coach_pair_key := jsonb_build_array(rec.coach_id, rec.course_id, rec.relationship_type)::text;
    if v_coach_seen_rows ? v_coach_row_key then
      c := public._jsonb_inc(c, array['user_coaches','skipped_dupe'], 1);
      continue;
    end if;
    v_coach_seen_rows := v_coach_seen_rows || jsonb_build_object(v_coach_row_key, true);
    if rec.is_active and (rec.ended_at is null or rec.ended_at > now())
      and v_coach_active_keys ? v_coach_pair_key then
      c := public._jsonb_inc(c, array['user_coaches','merged'], 1);
      if not v_dry_run then
        update public.user_coaches d set
          assigned_at = least(d.assigned_at, rec.assigned_at),
          ended_at = case when d.ended_at is null or rec.ended_at is null then null else greatest(d.ended_at, rec.ended_at) end
        where d.id = (select active.id from public.user_coaches active
          where active.user_id = _dest and active.coach_id = rec.coach_id
            and active.course_id is not distinct from rec.course_id and active.relationship_type = rec.relationship_type
            and active.is_active and (active.ended_at is null or active.ended_at > now())
          order by active.assigned_at, active.id limit 1);
      end if;
    else
      c := public._jsonb_inc(c, array['user_coaches','moved'], 1);
      if rec.is_active and (rec.ended_at is null or rec.ended_at > now()) then
        v_coach_active_keys := v_coach_active_keys || jsonb_build_object(v_coach_pair_key, true);
      end if;
      if not v_dry_run then
        insert into public.user_coaches (user_id, coach_id, is_active, assigned_at, ended_at, course_id, relationship_type)
        values (_dest, rec.coach_id, rec.is_active, rec.assigned_at, rec.ended_at, rec.course_id, rec.relationship_type);
      end if;
    end if;
  end loop;

  ----------------------------------------------------------------------
  -- 9) Partnerships (COPY)
  ----------------------------------------------------------------------
  v_tmp_count := (select count(*) from public.partnership_users where user_id = _source);
  c := public._jsonb_inc(c, ARRAY['partnership_users','moved'], v_tmp_count);

  if not v_dry_run then
    insert into public.partnership_users (partnership_id, user_id)
    select partnership_id, _dest
    from public.partnership_users
    where user_id = _source
    on conflict (partnership_id, user_id) do nothing;
  end if;

  ----------------------------------------------------------------------
  -- 10) User node progress (COPY + merge on dest)
  ----------------------------------------------------------------------
  if v_dry_run then
    v_tmp_count := (select count(*) from public.user_node_progress s where user_id = _source
      and not exists (select 1 from public.user_node_progress d where d.user_id = _dest and d.node_id = s.node_id));
    c := public._jsonb_inc(c, ARRAY['progress','moved'], v_tmp_count);
    v_tmp_count := (select count(*) from public.user_node_progress s where user_id = _source
      and exists (select 1 from public.user_node_progress d where d.user_id = _dest and d.node_id = s.node_id));
    c := public._jsonb_inc(c, ARRAY['progress','merged'], v_tmp_count);
  else
    for rec in
      select
        s.node_id,
        s.status as s_status,
        s.first_started_at as s_start,
        s.completed_at as s_complete,
        s.progress_json as s_json,
        d.status as d_status,
        d.first_started_at as d_start,
        d.completed_at as d_complete,
        d.progress_json as d_json
      from public.user_node_progress s
      left join public.user_node_progress d
        on d.user_id = _dest
       and d.node_id = s.node_id
      where s.user_id = _source
    loop
      if rec.d_status is not null then
        update public.user_node_progress up
           set status = case
                          when public._status_rank(rec.d_status) >= public._status_rank(rec.s_status)
                            then rec.d_status
                          else rec.s_status
                        end,
               first_started_at = least(
                                    coalesce(rec.d_start, rec.s_start),
                                    coalesce(rec.s_start, rec.d_start)
                                  ),
               completed_at     = greatest(
                                    coalesce(rec.d_complete, rec.s_complete),
                                    coalesce(rec.s_complete, rec.d_complete)
                                  ),
               progress_json    = case v_progress_json_strategy
                                   when 'prefer_source' then rec.s_json
                                   when 'deep_merge' then
                                     coalesce(rec.d_json, '{}'::jsonb)
                                     || coalesce(rec.s_json, '{}'::jsonb)
                                   else rec.d_json
                                 end
         where up.user_id = _dest
           and up.node_id = rec.node_id;

        c := public._jsonb_inc(c, ARRAY['progress','merged'], 1);
      else
        insert into public.user_node_progress (
          user_id, node_id, status, first_started_at, completed_at, progress_json
        )
        values (
          _dest,
          rec.node_id,
          rec.s_status,
          rec.s_start,
          rec.s_complete,
          rec.s_json
        );

        c := public._jsonb_inc(c, ARRAY['progress','moved'], 1);
      end if;
    end loop;
  end if;

  ----------------------------------------------------------------------
  -- 11) Smart doc responses (+ values): one response per member/block.
  -- Keep each winning response and its values as a unit; never mix submitted
  -- metadata from one account with field values from another.
  ----------------------------------------------------------------------
  c := jsonb_set(c, '{smart_docs}', jsonb_build_object('reassigned', 0, 'merged', 0, 'kept_dest', 0));
  if not v_dry_run then
    v_previous_smart_doc_context := current_setting('reboot.account_transfer_smart_docs', true);
    perform set_config('reboot.account_transfer_smart_docs', jsonb_build_object('source', _source, 'dest', _dest)::text, true);
  end if;
  for rec in select * from public.smart_doc_responses where user_id = _source order by id
  loop
    select * into v_existing_response from public.smart_doc_responses
      where user_id = _dest and content_block_id = rec.content_block_id for update;
    v_use_source_response := v_existing_response.id is null or v_sdoc_strategy = 'keep_source';
    if v_existing_response.id is not null and v_sdoc_strategy = 'keep_latest_submitted' then
      v_use_source_response :=
        (case when rec.status = 'submitted' then 1 else 0 end,
         coalesce(rec.submitted_at, '-infinity'::timestamptz), rec.updated_at)
        > (case when v_existing_response.status = 'submitted' then 1 else 0 end,
           coalesce(v_existing_response.submitted_at, '-infinity'::timestamptz), v_existing_response.updated_at);
    end if;
    if not v_use_source_response then
      c := public._jsonb_inc(c, array['smart_docs','kept_dest'], 1);
      continue;
    end if;
    c := public._jsonb_inc(c, array['smart_docs',case when v_existing_response.id is null then 'reassigned' else 'merged' end], 1);
    if v_dry_run then continue; end if;
    if v_existing_response.id is null then
      insert into public.smart_doc_responses (
        content_block_id, user_id, status, started_at, submitted_at, created_by, updated_by, updated_at
      ) values (
        rec.content_block_id, _dest, rec.status, rec.started_at, rec.submitted_at,
        rec.created_by, rec.updated_by, rec.updated_at
      ) returning id into v_new_response_id;
    else
      v_new_response_id := v_existing_response.id;
      update public.smart_doc_responses set status = rec.status, started_at = rec.started_at,
        submitted_at = rec.submitted_at, created_by = rec.created_by,
        updated_by = rec.updated_by, updated_at = rec.updated_at where id = v_new_response_id;
      delete from public.smart_doc_response_values where response_id = v_new_response_id;
    end if;
    insert into public.smart_doc_response_values (
      response_id, prompt_id, value_json, created_by, updated_by, updated_at
    ) select v_new_response_id, prompt_id, value_json, created_by, updated_by, updated_at
      from public.smart_doc_response_values where response_id = rec.id;
  end loop;
  if not v_dry_run then
    perform set_config('reboot.account_transfer_smart_docs', coalesce(v_previous_smart_doc_context, ''), true);
  end if;

  ----------------------------------------------------------------------
  -- 12) Analytics + attention logs (COPY)
  ----------------------------------------------------------------------
  v_tmp_count := (select count(*) from public.resource_access where user_id = _source);
  c := public._jsonb_inc(c, ARRAY['resource_access','moved'], v_tmp_count);

  v_tmp_count := (select count(*) from public.search_analytics where user_id = _source);
  c := public._jsonb_inc(c, ARRAY['search_analytics','moved'], v_tmp_count);

  v_tmp_count := (select count(*) from public.user_attention_status_log where user_id = _source);
  c := public._jsonb_inc(c, ARRAY['attention_log','moved'], v_tmp_count);

  if not v_dry_run then
    insert into public.resource_access (resource_id, user_id, accessed_at, session_id)
    select resource_id, _dest, accessed_at, session_id
    from public.resource_access
    where user_id = _source;

    insert into public.search_analytics (query, results_count, user_id, searched_at, session_id)
    select query, results_count, _dest, searched_at, session_id
    from public.search_analytics
    where user_id = _source;

    insert into public.user_attention_status_log (
      user_id,
      manual_status,
      reason,
      prev_manual_status,
      prev_reason,
      changed_by,
      changed_at,
      change_source
    )
    select
      _dest,
      manual_status,
      reason,
      prev_manual_status,
      prev_reason,
      changed_by,
      changed_at,
      change_source
    from public.user_attention_status_log
    where user_id = _source;
  end if;

  ----------------------------------------------------------------------
  -- 13) Optional authorship reassignment (still MOVE semantics, opt-in)
  ----------------------------------------------------------------------
  if v_reassign_authorship then
    -- Count the references to be reassigned, including all three node fields.
    v_tmp_count := (select count(*) from public.content_nodes where owner_id = _source)
      + (select count(*) from public.content_nodes where created_by = _source)
      + (select count(*) from public.content_nodes where updated_by = _source)
      + (select count(*) from public.resources where created_by = _source)
      + (select count(*) from public.smart_docs where created_by = _source)
      + (select count(*) from public.tags where created_by = _source);
    c := public._jsonb_inc(c, ARRAY['authorship','reassigned'], v_tmp_count);
  end if;
  if not v_dry_run and v_reassign_authorship then
    update public.content_nodes set owner_id  = _dest where owner_id  = _source;
    update public.content_nodes set created_by = _dest where created_by = _source;
    update public.content_nodes set updated_by = _dest where updated_by = _source;
    update public.resources     set created_by = _dest where created_by = _source;
    update public.smart_docs    set created_by = _dest where created_by = _source;
    update public.tags          set created_by = _dest where created_by = _source;
  end if;

  ----------------------------------------------------------------------
  -- Finalize + log
  ----------------------------------------------------------------------
  c := c || jsonb_build_object('ghl_identity', jsonb_build_object('updated', 1));
  if not v_dry_run then
    -- Member scheduling still reads ghl_user_id as the contact ID. Staff
    -- accounts are refused above because the same legacy column means a staff
    -- user ID for coaches. Both member fields must agree after the copy.
    update public.profiles d set ghl_contact_id = v_destination_ghl_contact_id,
      ghl_user_id = v_destination_ghl_contact_id,
      introduced_at = least(d.introduced_at, s.introduced_at),
      attention_status_manual = coalesce(d.attention_status_manual, s.attention_status_manual),
      attention_status_manual_reason = case when d.attention_status_manual is null then s.attention_status_manual_reason else d.attention_status_manual_reason end,
      attention_status_updated_by = case when d.attention_status_manual is null then s.attention_status_updated_by else d.attention_status_updated_by end,
      attention_status_updated_at = case when d.attention_status_manual is null then s.attention_status_updated_at else d.attention_status_updated_at end
    from public.profiles s where s.id = _source and d.id = _dest;
    perform public.apply_user_attention_auto(_dest);
  end if;
  v_result := jsonb_build_object(
    'source', _source,
    'dest', _dest,
    'dry_run', v_dry_run,
    'counts', c,
    'request_id', v_request_id,
    'ghl', jsonb_build_object('destination_email', v_destination_email,
      'contact_id', v_destination_ghl_contact_id)
  );

  update public.user_merge_log
     set finished_at = now(),
         result_json = v_result
   where id = v_log_id;

  return v_result;
end;
$$;



-- The HTTP route supplies a service-role client after requireAdmin succeeds.
-- Both RPC entry points enforce the same database guard.
create or replace function public.transfer_user_data_admin(
  _source uuid, _dest uuid, _options jsonb default '{}'::jsonb
) returns jsonb
language sql security definer set search_path = pg_catalog, public
as $$
  select public.transfer_user_data(_source, _dest, coalesce(_options, '{}'::jsonb));
$$;

-- A versioned entry point prevents new application code from silently invoking
-- the old function that ignored verified GHL identities and request IDs.
create or replace function public.transfer_user_data_admin_v2(
  _source uuid, _dest uuid, _options jsonb default '{}'::jsonb
) returns jsonb
language sql security definer set search_path = pg_catalog, public
as $$
  select public.transfer_user_data(_source, _dest, coalesce(_options, '{}'::jsonb));
$$;

revoke all on function public.transfer_user_data(uuid, uuid, jsonb),
  public.transfer_user_data_admin(uuid, uuid, jsonb),
  public.transfer_user_data_admin_v2(uuid, uuid, jsonb) from public, anon, authenticated;
grant execute on function public.transfer_user_data(uuid, uuid, jsonb),
  public.transfer_user_data_admin(uuid, uuid, jsonb),
  public.transfer_user_data_admin_v2(uuid, uuid, jsonb) to service_role;

commit;
